{"command": "cd /workspace && cat > flags.go <<'EOF'
// Package-level flag parsing that mirrors the behaviour of the POSIX/GNU-style
// flag parser used by the original implementation.
package main

import (
	"fmt"
	"strings"
)

// Flag describes a single command-line option.
type Flag struct {
	Name      string // long name, without leading dashes
	Short     string // optional single-letter shorthand
	Usage     string // usage string; a back-quoted word names the value
	Value     string // current value
	Bool      bool   // whether the flag is boolean
	Changed   bool
	IsDefault bool
}

// FlagSet holds a collection of flags plus any positional arguments.
type FlagSet struct {
	flags    []*Flag
	byName   map[string]*Flag
	byShort  map[byte]*Flag
	Args     []string
	trailing []string
}

// NewFlagSet creates an empty flag set.
func NewFlagSet() *FlagSet {
	return &FlagSet{
		byName:  map[string]*Flag{},
		byShort: map[byte]*Flag{},
	}
}

// Bool registers a boolean flag.
func (f *FlagSet) Bool(name, short, usage string) *Flag {
	fl := &Flag{Name: name, Short: short, Usage: usage, Bool: true, Value: "false"}
	f.register(fl)
	return fl
}

// String registers a string-valued flag.
func (f *FlagSet) String(name, short, usage string) *Flag {
	fl := &Flag{Name: name, Short: short, Usage: usage}
	f.register(fl)
	return fl
}

func (f *FlagSet) register(fl *Flag) {
	f.flags = append(f.flags, fl)
	f.byName[fl.Name] = fl
	if fl.Short != "" {
		f.byShort[fl.Short[0]] = fl
	}
}

// Changed reports whether the named flag was seen on the command line.
func (f *FlagSet) Changed(name string) bool {
	fl, ok := f.byName[name]
	return ok && fl.Changed
}

// Value returns the current value of the named flag.
func (f *FlagSet) Value(name string) string {
	if fl, ok := f.byName[name]; ok {
		return fl.Value
	}
	return ""
}

// BoolValue returns the boolean value of the named flag.
func (f *FlagSet) BoolValue(name string) bool {
	return f.Value(name) == "true"
}

func (f *FlagSet) setBool(fl *Flag, value string) error {
	switch value {
	case "1", "t", "T", "true", "TRUE", "True":
		fl.Value = "true"
	case "0", "f", "F", "false", "FALSE", "False":
		fl.Value = "false"
	default:
		return fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", value, flagDisplay(fl), value)
	}
	fl.Changed = true
	return nil
}

func (f *FlagSet) setString(fl *Flag, value string) {
	fl.Value = value
	fl.Changed = true
}

func flagDisplay(fl *Flag) string {
	if fl.Short != "" {
		return fmt.Sprintf("-%s, --%s", fl.Short, fl.Name)
	}
	return fmt.Sprintf("--%s", fl.Name)
}

// Parse consumes args, filling in flag values and collecting positional
// arguments.
func (f *FlagSet) Parse(args []string) error {
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			f.Args = append(f.Args, s)
			continue
		}
		var err error
		if s[1] == '-' {
			if len(s) == 2 {
				f.Args = append(f.Args, args...)
				break
			}
			args, err = f.parseLong(s, args)
		} else {
			args, err = f.parseShort(s, args)
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (f *FlagSet) parseLong(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return args, fmt.Errorf("bad flag syntax: %s", s)
	}
	var value string
	hadValue := false
	if idx := strings.IndexByte(name, '='); idx >= 0 {
		value = name[idx+1:]
		name = name[:idx]
		hadValue = true
	}
	fl, ok := f.byName[name]
	if !ok {
		return args, fmt.Errorf("unknown flag: --%s", name)
	}
	if !hadValue {
		if fl.Bool {
			value = "true"
		} else if len(args) > 0 {
			value = args[0]
			args = args[1:]
		} else {
			return args, fmt.Errorf("flag needs an argument: %s", s)
		}
	}
	if fl.Bool {
		return args, f.setBool(fl, value)
	}
	f.setString(fl, value)
	return args, nil
}

func (f *FlagSet) parseShort(s string, args []string) ([]string, error) {
	shorthands := s[1:]
	for len(shorthands) > 0 {
		c := shorthands[0]
		fl, ok := f.byShort[c]
		if !ok {
			return args, fmt.Errorf("unknown shorthand flag: %q in -%s", string(c), shorthands)
		}
		var value string
		rest := ""
		switch {
		case len(shorthands) > 2 && shorthands[1] == '=':
			value = shorthands[2:]
		case fl.Bool:
			value = "true"
			if len(shorthands) > 1 {
				rest = shorthands[1:]
			}
		case len(shorthands) > 1:
			value = shorthands[1:]
		case len(args) > 0:
			value = args[0]
			args = args[1:]
		default:
			return args, fmt.Errorf("flag needs an argument: %q in -%s", string(c), shorthands)
		}
		if fl.Bool {
			if err := f.setBool(fl, value); err != nil {
				return args, err
			}
		} else {
			f.setString(fl, value)
		}
		shorthands = rest
	}
	return args, nil
}

// Usages renders the flag section of the help output.
func (f *FlagSet) Usages() string {
	type entry struct {
		prefix string
		usage  string
	}
	var entries []entry
	maxlen := 0
	for _, fl := range f.sorted() {
		var line string
		if fl.Short != "" {
			line = fmt.Sprintf("  -%s, --%s", fl.Short, fl.Name)
		} else {
			line = fmt.Sprintf("      --%s", fl.Name)
		}
		varname, usage := unquoteUsage(fl)
		if varname != "" {
			line += " " + varname
		}
		// the marker character accounts for the single space that separates
		// the flag from its usage
		if len(line)+1 > maxlen {
			maxlen = len(line) + 1
		}
		entries = append(entries, entry{prefix: line, usage: usage})
	}
	var b strings.Builder
	for _, e := range entries {
		spacing := strings.Repeat(" ", maxlen-len(e.prefix))
		b.WriteString(e.prefix)
		b.WriteString(" ")
		b.WriteString(spacing)
		b.WriteString(" ")
		b.WriteString(e.usage)
		b.WriteString("\n")
	}
	return b.String()
}

func (f *FlagSet) sorted() []*Flag {
	out := make([]*Flag, len(f.flags))
	copy(out, f.flags)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].Name < out[j-1].Name; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// unquoteUsage extracts the value placeholder name from the usage string and
// strips the back quotes.
func unquoteUsage(fl *Flag) (name, usage string) {
	usage = fl.Usage
	for i := 0; i < len(usage); i++ {
		if usage[i] == '`' {
			for j := i + 1; j < len(usage); j++ {
				if usage[j] == '`' {
					name = usage[i+1 : j]
					usage = usage[:i] + name + usage[j+1:]
					return name, usage
				}
			}
			break
		}
	}
	if fl.Bool {
		return "", usage
	}
	return "string", usage
}
EOF
gofmt -l flags.go; echo ok"}

