// FlagSet holds a collection of flags plus any positional arguments.
type FlagSet struct {
	flags    []*Flag
	byName   map[string]*Flag
	byShort  map[byte]*Flag
	Args     []string
	trailing []string
}

// NewFlagSet creates an empty flag set.
func NewFlagSet() *FlagSet {
	return &FlagSet{
		byName:  map[string]*Flag{},
		byShort: map[byte]*Flag{},
	}
}

// Bool registers a boolean flag.
func (f *FlagSet) Bool(name, short, usage string) *Flag {
	fl := &Flag{Name: name, Short: short, Usage: usage, Bool: true, Value: "false"}
	f.register(fl)
	return fl
}

// String registers a string-valued flag.
func (f *FlagSet) String(name, short, usage string) *Flag {
	fl := &Flag{Name: name, Short: short, Usage: usage}
	f.register(fl)
	return fl
}

func (f *FlagSet) register(fl *Flag) {
	f.flags = append(f.flags, fl)
	f.byName[fl.Name] = fl
	if fl.Short != "" {
		f.byShort[fl.Short[0]] = fl
	}
}

// Changed reports whether the named flag was seen on the command line.
func (f *FlagSet) Changed(name string) bool {
	fl, ok := f.byName[name]
	return ok && fl.Changed
}

// Value returns the current value of the named flag.
func (f *FlagSet) Value(name string) string {
	if fl, ok := f.byName[name]; ok {
		return fl.Value
	}
	return ""
}

// BoolValue returns the boolean value of the named flag.
func (f *FlagSet) BoolValue(name string) bool {
	return f.Value(name) == "true"
}

func (f *FlagSet) setBool(fl *Flag, value string) error {
	switch value {
	case "1", "t", "T", "true", "TRUE", "True":
		fl.Value = "true"
	case "0", "f", "F", "false", "FALSE", "False":
		fl.Value = "false"
	default:
		return fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", value, flagDisplay(fl), value)
	}
	fl.Changed = true
	return nil
}

func (f *FlagSet) setString(fl *Flag, value string) {
	fl.Value = value
	fl.Changed = true
}

func flagDisplay(fl *Flag) string {
	if fl.Short != "" {
		return fmt.Sprintf("-%s, --%s", fl.Short, fl.Name)
	}
	return fmt.Sprintf("--%s", fl.Name)
}

// Parse consumes args, filling in flag values and collecting positional
// arguments.
func (f *FlagSet) Parse(args []string) error {
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			f.Args = append(f.Args, s)
			continue
		}
		var err error
		if s[1] == '-' {
			if len(s) == 2 {
				f.Args = append(f.Args, args...)
				break
			}
			args, err = f.parseLong(s, args)
		} else {
			args, err = f.parseShort(s, args)
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (f *FlagSet) parseLong(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return args, fmt.Errorf("bad flag syntax: %s", s)
	}
	var value string
	hadValue := false
	if idx := strings.IndexByte(name, '='); idx >= 0 {
		value = name[idx+1:]
		name = name[:idx]
		hadValue = true
	}
	fl, ok := f.byName[name]
	if !ok {
		return args, fmt.Errorf("unknown flag: --%s", name)
	}
	if !hadValue {
		if fl.Bool {
			value = "true"
		} else if len(args) > 0 {
			value = args[0]
			args = args[1:]
		} else {
			return args, fmt.Errorf("flag needs an argument: %s", s)
		}
	}
	if fl.Bool {
		return args, f.setBool(fl, value)
	}
	f.setString(fl, value)
	return args, nil
}

func (f *FlagSet) parseShort(s string, args []string) ([]string, error) {
	shorthands := s[1:]
	for len(shorthands) > 0 {
		c := shorthands[0]
		fl, ok := f.byShort[c]
		if !ok {
			return args, fmt.Errorf("unknown shorthand flag: %q in -%s", string(c), shorthands)
		}
		var value string
		rest := ""
		switch {
		case len(shorthands) > 2 && shorthands[1] == '=':
			value = shorthands[2:]
		case fl.Bool:
			value = "true"
			if len(shorthands) > 1 {
				rest = shorthands[1:]
			}
		case len(shorthands) > 1:
			value = shorthands[1:]
		case len(args) > 0:
			value = args[0]
			args = args[1:]
		default:
			return args, fmt.Errorf("flag needs an argument: %q in -%s", string(c), shorthands)
		}
		if fl.Bool {
			if err := f.setBool(fl, value); err != nil {
				return args, err
			}
		} else {
			f.setString(fl, value)
		}
		shorthands = rest
	}
	return args, nil
}

// Usages renders the flag section of the help output.
func (f *FlagSet) Usages() string {
	type entry struct {
		prefix string
		usage  string
	}
	var entries []entry
	maxlen := 0
	for _, fl := range f.sorted() {
		var line string
		if fl.Short != "" {
			line = fmt.Sprintf("  -%s, --%s", fl.Short, fl.Name)
		} else {
			line = fmt.Sprintf("      --%s", fl.Name)
		}
		varname, usage := unquoteUsage(fl)
		if varname != "" {
			line += " " + varname
		}
		// the marker character accounts for the single space that separates
		// the flag from its usage
		if len(line)+1 > maxlen {
			maxlen = len(line) + 1
		}
		entries = append(entries, entry{prefix: line, usage: usage})
	}
	var b strings.Builder
	for _, e := range entries {
		spacing := strings.Repeat(" ", maxlen-len(e.prefix))
		b.WriteString(e.prefix)
		b.WriteString(" ")
		b.WriteString(spacing)
		b.WriteString(" ")
		b.WriteString(e.usage)
		b.WriteString("\n")
	}
	return b.String()
}

func (f *FlagSet) sorted() []*Flag {
	out := make([]*Flag, len(f.flags))
	copy(out, f.flags)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].Name < out[j-1].Name; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// unquoteUsage extracts the value placeholder name from the usage string and
// strips the back quotes.
func unquoteUsage(fl *Flag) (name, usage string) {
	usage = fl.Usage
	for i := 0; i < len(usage); i++ {
		if usage[i] == '`' {
			for j := i + 1; j < len(usage); j++ {
				if usage[j] == '`' {
					name = usage[i+1 : j]
					usage = usage[:i] + name + usage[j+1:]
					return name, usage
				}
			}
			break
		}
	}
	if fl.Bool {
		return "", usage
	}
	return "string", usage
}
EOF
gofmt -l flags.go; echo ok"}

{"command": "cd /workspace && cat > yaml.go <<'EOF'
// A small YAML reader that is sufficient for cheat's configuration file and
// cheatsheet front-matter.  It understands block and flow mappings/sequences,
// quoted and plain scalars, block scalars and comments.
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// yamlNode is a parsed YAML node.
type yamlNode struct {
	kind  int // 0 scalar, 1 sequence, 2 mapping
	tag   string
	value string
	quoted bool
	seq   []*yamlNode
	keys  []*yamlNode
	vals  []*yamlNode
	line  int // 1-based line number
}

const (
	yamlScalar = iota
	yamlSequence
	yamlMapping
)

type yamlParser struct {
	lines []yamlLine
	pos   int
}

type yamlLine struct {
	indent  int
	content string // content with the comment stripped
	raw     string
	num     int
}

func newYamlParser(text string) *yamlParser {
	p := &yamlParser{}
	for i, raw := range strings.Split(text, "\n") {
		trimmed := strings.TrimLeft(raw, " \t")
		indent := len(raw) - len(trimmed)
		content := stripYamlComment(trimmed)
		p.lines = append(p.lines, yamlLine{indent: indent, content: content, raw: raw, num: i + 1})
	}
	return p
}

func stripYamlComment(s string) string {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case c == '#' && !inSingle && !inDouble && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t'):
			return strings.TrimRight(s[:i], " \t")
		}
	}
	return strings.TrimRight(s, " \t")
}

func (p *yamlParser) peek() (yamlLine, bool) {
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.content != "" {
			return l, true
		}
		p.pos++
	}
	return yamlLine{}, false
}

func (p *yamlParser) next() (yamlLine, bool) {
	l, ok := p.peek()
	if ok {
		p.pos++
	}
	return l, ok
}

// parseDocument parses the whole document and returns the root node.
func (p *yamlParser) parseDocument() (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	n, err := p.parseBlock(l.indent)
	if err != nil {
		return nil, err
	}
	return n, nil
}

// parseBlock parses a block node whose entries are indented at least `indent`.
func (p *yamlParser) parseBlock(indent int) (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	if l.indent < indent {
		return nil, nil
	}
	if strings.HasPrefix(l.content, "- ") || l.content == "-" {
		return p.parseBlockSeq(l.indent)
	}
	return p.parseBlockMap(l.indent)
}

func (p *yamlParser) parseBlockSeq(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, tag: "!!seq"}
	for {
		l, ok := p.peek()
		if !ok || l.indent != indent {
			break
		}
		if !strings.HasPrefix(l.content, "- ") && l.content != "-" {
			break
		}
		rest := strings.TrimLeft(strings.TrimPrefix(l.content, "-"), " ")
		lineNum := l.num
		p.pos++
		if rest == "" {
			child, err := p.parseNested(indent)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = &yamlNode{kind: yamlScalar, tag: "!!null", line: lineNum}
			}
			node.seq = append(node.seq, child)
			continue
		}
		// an inline entry which may itself start a mapping
		child, err := p.parseInlineEntry(rest, indent, lineNum)
		if err != nil {
			return nil, err
		}
		node.seq = append(node.seq, child)
	}
	if len(node.seq) == 0 {
		return nil, nil
	}
	return node, nil
}

// parseInlineEntry parses the value following a "- " marker.
func (p *yamlParser) parseInlineEntry(rest string, indent, lineNum int) (*yamlNode, error) {
	if strings.Contains(rest, ": ") || strings.HasSuffix(rest, ":") {
		// a mapping whose first key is on this line
		node := &yamlNode{kind: yamlMapping, tag: "!!map", line: lineNum}
		// reparse the entry with a synthetic indentation
		p.pos--
		p.lines[p.pos].content = strings.Repeat(" ", indent+2) + rest
		child, err := p.parseBlockMap(indent + 2)
		if err != nil {
			return nil, err
		}
		_ = node
		return child, nil
	}
	n, err := parseScalar(rest, lineNum)
	if err != nil {
		return nil, err
	}
	return n, nil
}

func (p *yamlParser) parseBlockMap(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMapping, tag: "!!map"}
	if p.pos < len(p.lines) && node.line == 0 {
		node.line = p.lines[p.pos].num
	}
	for {
		l, ok := p.peek()
		if !ok || l.indent != indent {
			if ok && l.indent > indent {
				return nil, fmt.Errorf("yaml: line %d: mapping values are not allowed in this context", l.num)
			}
			break
		}
		key, rest, err := splitMapKey(l.content)
		if err != nil {
			return nil, err
		}
		if key == "" {
			return nil, fmt.Errorf("yaml: line %d: did not find expected node content", l.num)
		}
		keyNode, err := parseScalar(key, l.num)
		if err != nil {
			return nil, err
		}
		p.pos++
		var valNode *yamlNode
		if rest == "" {
			child, err := p.parseNested(indent)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = &yamlNode{kind: yamlScalar, tag: "!!null", line: l.num}
			}
			valNode = child
		} else if rest == "|" || rest == ">" || strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
			valNode = p.parseBlockScalar(rest, indent, l.num)
		} else {
			valNode, err = parseScalar(rest, l.num)
			if err != nil {
				return nil, err
			}
		}
		node.keys = append(node.keys, keyNode)
		node.vals = append(node.vals, valNode)
	}
	if len(node.keys) == 0 {
		return nil, nil
	}
	return node, nil
}

// parseNested parses the child node of a mapping/sequence entry that begins on
// the following line.
func (p *yamlParser) parseNested(indent int) (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	if l.indent <= indent {
		return nil, nil
	}
	return p.parseBlock(l.indent)
}

func (p *yamlParser) parseBlockScalar(header string, indent, lineNum int) *yamlNode {
	folded := strings.HasPrefix(header, ">")
	chomp := ""
	if strings.HasSuffix(header, "-") {
		chomp = "-"
	} else if strings.HasSuffix(header, "+") {
		chomp = "+"
	}
	var parts []string
	baseIndent := -1
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimRight(l.raw, " \t") == "" {
			parts = append(parts, "")
			p.pos++
			continue
		}
		if l.indent <= indent {
			break
		}
		if baseIndent < 0 {
			baseIndent = l.indent
		}
		text := l.raw
		if len(text) > baseIndent {
			text = text[baseIndent:]
		} else {
			text = ""
		}
		parts = append(parts, text)
		p.pos++
	}
	// remove trailing blank lines unless a chomping indicator says otherwise
	for len(parts) > 0 && strings.TrimRight(parts[len(parts)-1], " \t") == "" {
		parts = parts[:len(parts)-1]
	}
	var value string
	if folded {
		value = strings.Join(parts, " ")
	} else {
		value = strings.Join(parts, "\n")
	}
	if chomp != "-" && value != "" {
		value += "\n"
	}
	return &yamlNode{kind: yamlScalar, tag: "!!str", value: value, quoted: true, line: lineNum}
}

// splitMapKey splits "key: value" honouring quoting.
func splitMapKey(s string) (key, rest string, err error) {
	inSingle, inDouble := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case (c == '[' || c == '{') && !inSingle && !inDouble:
			depth++
		case (c == ']' || c == '}') && !inSingle && !inDouble:
			depth--
		case c == ':' && !inSingle && !inDouble && depth == 0:
			if i+1 == len(s) {
				return s[:i], "", nil
			}
			if s[i+1] == ' ' || s[i+1] == '\t' {
				return s[:i], strings.TrimLeft(s[i+1:], " \t"), nil
			}
		}
	}
	return "", "", nil
}

// parseScalar parses a flow collection or scalar.
func parseScalar(s string, line int) (*yamlNode, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return &yamlNode{kind: yamlScalar, tag: "!!null", line: line}, nil
	}
	if strings.HasPrefix(s, "[") {
		return parseFlowSeq(s, line)
	}
	if strings.HasPrefix(s, "{") {
		return parseFlowMap(s, line)
	}
	if strings.HasPrefix(s, "- ") {
		// a compact sequence such as "- a" appearing where a value is expected
		return parseScalar("", line)
	}
	return parsePlainScalar(s, line)
}

func splitFlow(s string) ([]string, error) {
	// s starts with [ or { and ends with the matching close
	open := s[0]
	var close byte
	switch open {
	case '[':
		close = ']'
	case '{':
		close = '}'
	}
	depth := 0
	inSingle, inDouble := false, false
	var parts []string
	start := 1
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case (c == '[' || c == '{') && !inSingle && !inDouble:
			depth++
		case (c == ']' || c == '}') && !inSingle && !inDouble:
			depth--
			if depth == 0 && c == close {
				parts = append(parts, s[start:i])
				return parts, nil
			}
		case c == ',' && depth == 1 && !inSingle && !inDouble:
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	return nil, errors.New("yaml: did not find expected ',' or ']'")
}

func parseFlowSeq(s string, line int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, tag: "!!seq", line: line}
	if s == "[]" {
		return node, nil
	}
	parts, err := splitFlow(s)
	if err != nil {
		return nil, err
	}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		var child *yamlNode
		if part == "" {
			child = &yamlNode{kind: yamlScalar, tag: "!!null", line: line}
		} else {
			child, err = parseScalar(part, line)
			if err != nil {
				return nil, err
			}
		}
		node.seq = append(node.seq, child)
	}
	return node, nil
}

func parseFlowMap(s string, line int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMapping, tag: "!!map", line: line}
	if s == "{}" {
		return node, nil
	}
	parts, err := splitFlow(s)
	if err != nil {
		return nil, err
	}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		key, rest, _ := splitMapKey(part)
		keyNode, err := parseScalar(strings.TrimSpace(key), line)
		if err != nil {
			return nil, err
		}
		var valNode *yamlNode
		if strings.TrimSpace(rest) == "" {
			valNode = &yamlNode{kind: yamlScalar, tag: "!!null", line: line}
		} else {
			valNode, err = parseScalar(strings.TrimSpace(rest), line)
			if err != nil {
				return nil, err
			}
		}
		node.keys = append(node.keys, keyNode)
		node.vals = append(node.vals, valNode)
	}
	return node, nil
}

func parsePlainScalar(s string, line int) (*yamlNode, error) {
	if len(s) >= 1 && s[0] == '\'' {
		if len(s) < 2 || !strings.HasSuffix(s, "'") {
			return nil, fmt.Errorf("yaml: line %d: found unexpected end of stream", line)
		}
		inner := s[1 : len(s)-1]
		return &yamlNode{kind: yamlScalar, tag: "!!str", value: strings.ReplaceAll(inner, "''", "'"), quoted: true, line: line}, nil
	}
	if len(s) >= 1 && s[0] == '"' {
		if len(s) < 2 || !strings.HasSuffix(s, "\"") {
			return nil, fmt.Errorf("yaml: line %d: found unexpected end of stream", line)
		}
		inner := s[1 : len(s)-1]
		unq, err := strconv.Unquote("\"" + inner + "\"")
		if err != nil {
			unq = inner
		}
		return &yamlNode{kind: yamlScalar, tag: "!!str", value: unq, quoted: true, line: line}, nil
	}
	if strings.HasPrefix(s, "&") || strings.HasPrefix(s, "*") {
		// anchors and aliases are not supported; treat as a plain scalar
		idx := strings.IndexAny(s, " \t")
		if idx < 0 {
			return &yamlNode{kind: yamlScalar, tag: "!!str", value: s, line: line}, nil
		}
		return parseScalar(strings.TrimSpace(s[idx+1:]), line)
	}
	tag := resolveTag(s)
	return &yamlNode{kind: yamlScalar, tag: tag, value: s, line: line}, nil
}

func resolveTag(s string) string {
	switch s {
	case "true", "True", "TRUE", "false", "False", "FALSE", "yes", "Yes", "YES", "no", "No", "NO", "on", "On", "ON", "off", "Off", "OFF":
		return "!!bool"
	case "null", "Null", "NULL", "~":
		return "!!null"
	case "":
		return "!!null"
	}
	if _, err := strconv.ParseInt(s, 0, 64); err == nil {
		return "!!int"
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return "!!float"
	}
	return "!!str"
}

// Bool returns the boolean value of a node.
func (n *yamlNode) Bool() (bool, bool) {
	switch n.value {
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON", "y", "Y":
		return true, true
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF", "n", "N":
		return false, true
	}
	return false, false
}

// UnmarshalError describes a type mismatch encountered while decoding.
type UnmarshalError struct {
	Line  int
	Type  string
	Value string
	Tag   string
}

func (e UnmarshalError) String() string {
	value := ""
	if e.Tag != "!!seq" && e.Tag != "!!map" {
		if len(e.Value) > 10 {
			value = " `" + e.Value[:7] + "...`"
		} else {
			value = " `" + e.Value + "`"
		}
	}
	return fmt.Sprintf("line %d: cannot unmarshal %s%s into %s", e.Line, e.Tag, value, e.Type)
}
EOF
gofmt -l yaml.go; echo ok"}

