	tag   string
	value string
	quoted bool
	seq   []*yamlNode
	keys  []*yamlNode
	vals  []*yamlNode
	line  int // 1-based line number
}

const (
	yamlScalar = iota
	yamlSequence
	yamlMapping
)

type yamlParser struct {
	lines []yamlLine
	pos   int
}

type yamlLine struct {
	indent  int
	content string // content with the comment stripped
	raw     string
	num     int
}

func newYamlParser(text string) *yamlParser {
	p := &yamlParser{}
	for i, raw := range strings.Split(text, "\n") {
		trimmed := strings.TrimLeft(raw, " \t")
		indent := len(raw) - len(trimmed)
		content := stripYamlComment(trimmed)
		p.lines = append(p.lines, yamlLine{indent: indent, content: content, raw: raw, num: i + 1})
	}
	return p
}

func stripYamlComment(s string) string {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case c == '#' && !inSingle && !inDouble && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t'):
			return strings.TrimRight(s[:i], " \t")
		}
	}
	return strings.TrimRight(s, " \t")
}

func (p *yamlParser) peek() (yamlLine, bool) {
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.content != "" {
			return l, true
		}
		p.pos++
	}
	return yamlLine{}, false
}

func (p *yamlParser) next() (yamlLine, bool) {
	l, ok := p.peek()
	if ok {
		p.pos++
	}
	return l, ok
}

// parseDocument parses the whole document and returns the root node.
func (p *yamlParser) parseDocument() (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	n, err := p.parseBlock(l.indent)
	if err != nil {
		return nil, err
	}
	return n, nil
}

// parseBlock parses a block node whose entries are indented at least `indent`.
func (p *yamlParser) parseBlock(indent int) (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	if l.indent < indent {
		return nil, nil
	}
	if strings.HasPrefix(l.content, "- ") || l.content == "-" {
		return p.parseBlockSeq(l.indent)
	}
	return p.parseBlockMap(l.indent)
}

func (p *yamlParser) parseBlockSeq(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, tag: "!!seq"}
	for {
		l, ok := p.peek()
		if !ok || l.indent != indent {
			break
		}
		if !strings.HasPrefix(l.content, "- ") && l.content != "-" {
			break
		}
		rest := strings.TrimLeft(strings.TrimPrefix(l.content, "-"), " ")
		lineNum := l.num
		p.pos++
		if rest == "" {
			child, err := p.parseNested(indent)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = &yamlNode{kind: yamlScalar, tag: "!!null", line: lineNum}
			}
			node.seq = append(node.seq, child)
			continue
		}
		// an inline entry which may itself start a mapping
		child, err := p.parseInlineEntry(rest, indent, lineNum)
		if err != nil {
			return nil, err
		}
		node.seq = append(node.seq, child)
	}
	if len(node.seq) == 0 {
		return nil, nil
	}
	return node, nil
}

// parseInlineEntry parses the value following a "- " marker.
func (p *yamlParser) parseInlineEntry(rest string, indent, lineNum int) (*yamlNode, error) {
	if strings.Contains(rest, ": ") || strings.HasSuffix(rest, ":") {
		// a mapping whose first key is on this line
		node := &yamlNode{kind: yamlMapping, tag: "!!map", line: lineNum}
		// reparse the entry with a synthetic indentation
		p.pos--
		p.lines[p.pos].content = strings.Repeat(" ", indent+2) + rest
		child, err := p.parseBlockMap(indent + 2)
		if err != nil {
			return nil, err
		}
		_ = node
		return child, nil
	}
	n, err := parseScalar(rest, lineNum)
	if err != nil {
		return nil, err
	}
	return n, nil
}

func (p *yamlParser) parseBlockMap(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMapping, tag: "!!map"}
	if p.pos < len(p.lines) && node.line == 0 {
		node.line = p.lines[p.pos].num
	}
	for {
		l, ok := p.peek()
		if !ok || l.indent != indent {
			if ok && l.indent > indent {
				return nil, fmt.Errorf("yaml: line %d: mapping values are not allowed in this context", l.num)
			}
			break
		}
		key, rest, err := splitMapKey(l.content)
		if err != nil {
			return nil, err
		}
		if key == "" {
			return nil, fmt.Errorf("yaml: line %d: did not find expected node content", l.num)
		}
		keyNode, err := parseScalar(key, l.num)
		if err != nil {
			return nil, err
		}
		p.pos++
		var valNode *yamlNode
		if rest == "" {
			child, err := p.parseNested(indent)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = &yamlNode{kind: yamlScalar, tag: "!!null", line: l.num}
			}
			valNode = child
		} else if rest == "|" || rest == ">" || strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
			valNode = p.parseBlockScalar(rest, indent, l.num)
		} else {
			valNode, err = parseScalar(rest, l.num)
			if err != nil {
				return nil, err
			}
		}
		node.keys = append(node.keys, keyNode)
		node.vals = append(node.vals, valNode)
	}
	if len(node.keys) == 0 {
		return nil, nil
	}
	return node, nil
}

// parseNested parses the child node of a mapping/sequence entry that begins on
// the following line.
func (p *yamlParser) parseNested(indent int) (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	if l.indent <= indent {
		return nil, nil
	}
	return p.parseBlock(l.indent)
}

func (p *yamlParser) parseBlockScalar(header string, indent, lineNum int) *yamlNode {
	folded := strings.HasPrefix(header, ">")
	chomp := ""
	if strings.HasSuffix(header, "-") {
		chomp = "-"
	} else if strings.HasSuffix(header, "+") {
		chomp = "+"
	}
	var parts []string
	baseIndent := -1
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimRight(l.raw, " \t") == "" {
			parts = append(parts, "")
			p.pos++
			continue
		}
		if l.indent <= indent {
			break
		}
		if baseIndent < 0 {
			baseIndent = l.indent
		}
		text := l.raw
		if len(text) > baseIndent {
			text = text[baseIndent:]
		} else {
			text = ""
		}
		parts = append(parts, text)
		p.pos++
	}
	// remove trailing blank lines unless a chomping indicator says otherwise
	for len(parts) > 0 && strings.TrimRight(parts[len(parts)-1], " \t") == "" {
		parts = parts[:len(parts)-1]
	}
	var value string
	if folded {
		value = strings.Join(parts, " ")
	} else {
		value = strings.Join(parts, "\n")
	}
	if chomp != "-" && value != "" {
		value += "\n"
	}
	return &yamlNode{kind: yamlScalar, tag: "!!str", value: value, quoted: true, line: lineNum}
}

// splitMapKey splits "key: value" honouring quoting.
func splitMapKey(s string) (key, rest string, err error) {
	inSingle, inDouble := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case (c == '[' || c == '{') && !inSingle && !inDouble:
			depth++
		case (c == ']' || c == '}') && !inSingle && !inDouble:
			depth--
		case c == ':' && !inSingle && !inDouble && depth == 0:
			if i+1 == len(s) {
				return s[:i], "", nil
			}
			if s[i+1] == ' ' || s[i+1] == '\t' {
				return s[:i], strings.TrimLeft(s[i+1:], " \t"), nil
			}
		}
	}
	return "", "", nil
}

// parseScalar parses a flow collection or scalar.
func parseScalar(s string, line int) (*yamlNode, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return &yamlNode{kind: yamlScalar, tag: "!!null", line: line}, nil
	}
	if strings.HasPrefix(s, "[") {
		return parseFlowSeq(s, line)
	}
	if strings.HasPrefix(s, "{") {
		return parseFlowMap(s, line)
	}
	if strings.HasPrefix(s, "- ") {
		// a compact sequence such as "- a" appearing where a value is expected
		return parseScalar("", line)
	}
	return parsePlainScalar(s, line)
}

func splitFlow(s string) ([]string, error) {
	// s starts with [ or { and ends with the matching close
	open := s[0]
	var close byte
	switch open {
	case '[':
		close = ']'
	case '{':
		close = '}'
	}
	depth := 0
	inSingle, inDouble := false, false
	var parts []string
	start := 1
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case (c == '[' || c == '{') && !inSingle && !inDouble:
			depth++
		case (c == ']' || c == '}') && !inSingle && !inDouble:
			depth--
			if depth == 0 && c == close {
				parts = append(parts, s[start:i])
				return parts, nil
			}
		case c == ',' && depth == 1 && !inSingle && !inDouble:
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	return nil, errors.New("yaml: did not find expected ',' or ']'")
}

func parseFlowSeq(s string, line int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, tag: "!!seq", line: line}
	if s == "[]" {
		return node, nil
	}
	parts, err := splitFlow(s)
	if err != nil {
		return nil, err
	}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		var child *yamlNode
		if part == "" {
			child = &yamlNode{kind: yamlScalar, tag: "!!null", line: line}
		} else {
			child, err = parseScalar(part, line)
			if err != nil {
				return nil, err
			}
		}
		node.seq = append(node.seq, child)
	}
	return node, nil
}

func parseFlowMap(s string, line int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMapping, tag: "!!map", line: line}
	if s == "{}" {
		return node, nil
	}
	parts, err := splitFlow(s)
	if err != nil {
		return nil, err
	}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		key, rest, _ := splitMapKey(part)
		keyNode, err := parseScalar(strings.TrimSpace(key), line)
		if err != nil {
			return nil, err
		}
		var valNode *yamlNode
		if strings.TrimSpace(rest) == "" {
			valNode = &yamlNode{kind: yamlScalar, tag: "!!null", line: line}
		} else {
			valNode, err = parseScalar(strings.TrimSpace(rest), line)
			if err != nil {
				return nil, err
			}
		}
		node.keys = append(node.keys, keyNode)
		node.vals = append(node.vals, valNode)
	}
	return node, nil
}

func parsePlainScalar(s string, line int) (*yamlNode, error) {
	if len(s) >= 1 && s[0] == '\'' {
		if len(s) < 2 || !strings.HasSuffix(s, "'") {
			return nil, fmt.Errorf("yaml: line %d: found unexpected end of stream", line)
		}
		inner := s[1 : len(s)-1]
		return &yamlNode{kind: yamlScalar, tag: "!!str", value: strings.ReplaceAll(inner, "''", "'"), quoted: true, line: line}, nil
	}
	if len(s) >= 1 && s[0] == '"' {
		if len(s) < 2 || !strings.HasSuffix(s, "\"") {
			return nil, fmt.Errorf("yaml: line %d: found unexpected end of stream", line)
		}
		inner := s[1 : len(s)-1]
		unq, err := strconv.Unquote("\"" + inner + "\"")
		if err != nil {
			unq = inner
		}
		return &yamlNode{kind: yamlScalar, tag: "!!str", value: unq, quoted: true, line: line}, nil
	}
	if strings.HasPrefix(s, "&") || strings.HasPrefix(s, "*") {
		// anchors and aliases are not supported; treat as a plain scalar
		idx := strings.IndexAny(s, " \t")
		if idx < 0 {
			return &yamlNode{kind: yamlScalar, tag: "!!str", value: s, line: line}, nil
		}
		return parseScalar(strings.TrimSpace(s[idx+1:]), line)
	}
	tag := resolveTag(s)
	return &yamlNode{kind: yamlScalar, tag: tag, value: s, line: line}, nil
}

func resolveTag(s string) string {
	switch s {
	case "true", "True", "TRUE", "false", "False", "FALSE", "yes", "Yes", "YES", "no", "No", "NO", "on", "On", "ON", "off", "Off", "OFF":
		return "!!bool"
	case "null", "Null", "NULL", "~":
		return "!!null"
	case "":
		return "!!null"
	}
	if _, err := strconv.ParseInt(s, 0, 64); err == nil {
		return "!!int"
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return "!!float"
	}
	return "!!str"
}

// Bool returns the boolean value of a node.
func (n *yamlNode) Bool() (bool, bool) {
	switch n.value {
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON", "y", "Y":
		return true, true
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF", "n", "N":
		return false, true
	}
	return false, false
}

// UnmarshalError describes a type mismatch encountered while decoding.
type UnmarshalError struct {
	Line  int
	Type  string
	Value string
	Tag   string
}

func (e UnmarshalError) String() string {
	value := ""
	if e.Tag != "!!seq" && e.Tag != "!!map" {
		if len(e.Value) > 10 {
			value = " `" + e.Value[:7] + "...`"
		} else {
			value = " `" + e.Value + "`"
		}
	}
	return fmt.Sprintf("line %d: cannot unmarshal %s%s into %s", e.Line, e.Tag, value, e.Type)
}
