// locateConfig returns the path of the configuration file, or an empty string
// when it could not be found.
func locateConfig() string {
	for _, candidate := range configPathCandidates() {
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
	}
	return ""
}

// defaultConfigPath returns the location a new configuration file would be
// written to.
func defaultConfigPath() string {
	if env := os.Getenv("CHEAT_CONFIG_PATH"); env != "" {
		return env
	}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		return filepath.Join(xdg, "cheat", "conf.yml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "/etc/cheat/conf.yml"
	}
	return filepath.Join(home, ".config", "cheat", "conf.yml")
}

// expandHome expands a leading ~ in a path.
func expandHome(p string) string {
	if p == "~" || strings.HasPrefix(p, "~/") {
		home, err := os.UserHomeDir()
		if err == nil {
			if p == "~" {
				return home
			}
			return filepath.Join(home, p[2:])
		}
	}
	return p
}

// Load reads and validates the configuration file.
func Load(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("could not read config file: %s", err)
	}
	root, err := parseYamlDocument(string(data))
	if err != nil {
		return nil, fmt.Errorf("could not unmarshal yaml: %s", err)
	}
	conf := &Config{Path: path, Style: "monokai", Formatter: "terminal256"}
	if root != nil && root.kind == yamlMapping {
		for i, key := range root.keys {
			val := root.vals[i]
			switch strings.ToLower(key.value) {
			case "editor":
				if s, ok, err := decodeString(val, "string"); err != nil {
					return nil, unmarshalErrors(err)
				} else if ok {
					conf.Editor = s
				}
			case "colorize":
				if b, ok, err := decodeBool(val, "bool"); err != nil {
					return nil, unmarshalErrors(err)
				} else if ok {
					conf.Colorize = b
				}
			case "style":
				if s, ok, err := decodeString(val, "string"); err != nil {
					return nil, unmarshalErrors(err)
				} else if ok {
					conf.Style = s
				}
			case "formatter":
				if s, ok, err := decodeString(val, "string"); err != nil {
					return nil, unmarshalErrors(err)
				} else if ok {
					conf.Formatter = s
				}
			case "pager":
				if s, ok, err := decodeString(val, "string"); err != nil {
					return nil, unmarshalErrors(err)
				} else if ok {
					conf.Pager = s
				}
			case "cheatpaths":
				paths, err := decodeCheatpaths(val)
				if err != nil {
					return nil, unmarshalErrors(err)
				}
				conf.Cheatpaths = paths
			}
		}
	}

	// expand, clean and filter the cheatpaths
	var valid []Cheatpath
	for _, cp := range conf.Cheatpaths {
		p := filepath.Clean(expandHome(cp.Path))
		if st, err := os.Stat(p); err != nil || !st.IsDir() {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", p)
			continue
		}
		cp.Path = p
		valid = append(valid, cp)
	}
	conf.Cheatpaths = valid

	// resolve the editor
	conf.Editor = resolveEditor(conf.Editor)
	if conf.Editor == "" {
		return nil, fmt.Errorf("no editor set")
	}

	// validate the cheatpaths
	if len(conf.Cheatpaths) == 0 {
		return nil, fmt.Errorf("config error: no cheatpaths specified")
	}
	names := map[string]bool{}
	seen := map[string]bool{}
	for _, cp := range conf.Cheatpaths {
		if cp.Name == "" {
			return nil, fmt.Errorf("config error: cheatpath name cannot be empty")
		}
		if names[cp.Name] {
			return nil, fmt.Errorf("config error: cheatpath name is not unique: %s", cp.Name)
		}
		names[cp.Name] = true
		if seen[cp.Path] {
			return nil, fmt.Errorf("config error: cheatpath path is not unique: %s", cp.Path)
		}
		seen[cp.Path] = true
	}
	return conf, nil
}

// resolveEditor honours VISUAL and EDITOR before falling back to the
// configured value.
func resolveEditor(configured string) string {
	if v := os.Getenv("VISUAL"); strings.TrimSpace(v) != "" {
		return strings.TrimSpace(v)
	}
	if v := os.Getenv("EDITOR"); strings.TrimSpace(v) != "" {
		return strings.TrimSpace(v)
	}
	return strings.TrimSpace(configured)
}

// withCwdPath appends the directory-scoped cheatpath, if any.
func (c *Config) withCwdPath() error {
	dir := findCheatDir()
	if dir == "" {
		return nil
	}
	p := filepath.Clean(dir)
	for _, cp := range c.Cheatpaths {
		if cp.Name == "cwd" {
			return fmt.Errorf("config error: cheatpath name is not unique: cwd")
		}
		if cp.Path == p {
			return fmt.Errorf("config error: cheatpath path is not unique: %s", p)
		}
	}
	c.Cheatpaths = append(c.Cheatpaths, Cheatpath{Name: "cwd", Path: p, Readonly: false})
	return nil
}

// findCheatDir walks up from the working directory looking for a .cheat
// directory.
func findCheatDir() string {
	cwd, err := os.Getwd()
	if err != nil {
		return ""
	}
	cwd = filepath.Clean(cwd)
	for {
		candidate := filepath.Join(cwd, ".cheat")
		if st, err := os.Stat(candidate); err == nil && st.IsDir() {
			return candidate
		}
		parent := filepath.Dir(cwd)
		if parent == cwd {
			break
		}
		cwd = parent
	}
	return ""
}
