// unmarshalErrors normalises a decoder error into the message the original
// implementation produces.
func unmarshalErrors(err error) error {
	return fmt.Errorf("could not unmarshal yaml: %s", err)
}

// parseYamlDocument parses a YAML document, reporting scanner errors in the
// format used by the original implementation.
func parseYamlDocument(text string) (*yamlNode, error) {
	p := newYamlParser(text)
	root, err := p.parseDocument()
	if err != nil {
		return nil, err
	}
	// a stray unterminated flow collection is a scanner error
	for _, l := range p.lines {
		c := l.content
		if strings.HasPrefix(c, "-") || c == "" {
			continue
		}
		if _, _, kerr := splitMapKey(c); kerr != nil {
			return nil, kerr
		}
		if _, isMap := needsFlowCheck(c); isMap {
			return nil, fmt.Errorf("yaml: line %d: did not find expected node content", l.num)
		}
	}
	return root, nil
}

// needsFlowCheck reports whether a line opens a flow collection that is never
// closed.
func needsFlowCheck(c string) (string, bool) {
	depth := 0
	inSingle, inDouble := false, false
	for i := 0; i < len(c); i++ {
		switch c[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '[', '{':
			if !inSingle && !inDouble {
				depth++
			}
		case ']', '}':
			if !inSingle && !inDouble {
				depth--
			}
		}
	}
	if depth > 0 {
		return "", true
	}
	return "", false
}
