	if err != nil && answer == "" {
		if errors.Is(err, io.EOF) {
			return "", io.EOF
		}
		return "", err
	}
	return answer, nil
}

// prompt asks a yes/no question on stdout.
func prompt(question string) (bool, error) {
	fmt.Print(question)
	answer, err := readAnswer()
	if err != nil {
		return false, fmt.Errorf("failed to prompt: %s", err)
	}
	return answer == "" || answer == "y" || answer == "Y", nil
}

// cheatsheetsDir returns the directory that will hold the default cheatsheets.
func cheatsheetsDir(confPath string) string {
	return filepath.Join(filepath.Dir(confPath), "cheatsheets")
}

// runInstaller creates a configuration file and, optionally, the community
// cheatsheets.
func runInstaller(confPath string) error {
	clone, err := prompt("Would you like to download the community cheatsheets? [Y/n]: ")
	if err != nil {
		return fmt.Errorf("failed to prompt: %s", err)
	}
	dir := cheatsheetsDir(confPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory: %s", err)
	}
	if clone {
		community := filepath.Join(dir, "community")
		fmt.Printf("Cloning community cheatsheets to %s.\n", community)
		if err := cloneRepo(communityRepo, community); err != nil {
			return fmt.Errorf("failed to clone cheatsheets: %s", err)
		}
	}
	if err := os.MkdirAll(filepath.Join(dir, "personal"), 0755); err != nil {
		return fmt.Errorf("failed to create directory: %s", err)
	}
	if err := os.MkdirAll(filepath.Join(dir, "work"), 0755); err != nil {
		return fmt.Errorf("failed to create directory: %s", err)
	}
	if err := os.WriteFile(confPath, []byte(initConfig(confPath)), 0644); err != nil {
		return fmt.Errorf("failed to write config file: %s", err)
	}
	fmt.Printf("Created config file: %s\n", confPath)
	fmt.Printf("Please read this file for advanced configuration information.\n")
	return nil
}

// cloneRepo performs a shallow clone of a git repository.
func cloneRepo(url, dir string) error {
	if err := discoverRefs(url); err != nil {
		return fmt.Errorf("failed to clone cheatsheets: %s", err)
	}
	return fmt.Errorf("failed to clone cheatsheets: unsupported transport: %s", url)
}

// discoverRefs performs the git "ref discovery" handshake, which is the first
// thing that happens when contacting a remote.
func discoverRefs(url string) error {
	refs := url + "/info/refs?service=git-upload-pack"
	resp, err := http.Get(refs)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode == 404 {
		return errors.New("repository not found")
	}
	if resp.StatusCode != 200 {
		return fmt.Errorf("unknown error: http request failed: %s", resp.Status)
	}
	return nil
}
