package main

import (
	"fmt"
	"io"
	"sort"
	"strings"
)

// tabWriter renders rows of cells into aligned columns.  It reproduces the
// behaviour of the tabwriter used by the original implementation (a single
// space of padding after each column except the last).
type tabWriter struct {
	cells [][]string
}

func (w *tabWriter) add(cells ...string) {
	w.cells = append(w.cells, cells)
}

func (w *tabWriter) WriteTo(out io.Writer) {
	if len(w.cells) == 0 {
		return
	}
	cols := 0
	for _, row := range w.cells {
		if len(row) > cols {
			cols = len(row)
		}
	}
	widths := make([]int, cols)
	for _, row := range w.cells {
		for i, cell := range row {
			if i < cols-1 && len(cell) > widths[i] {
				widths[i] = len(cell)
			}
		}
	}
	for _, row := range w.cells {
		var b strings.Builder
		for i, cell := range row {
			b.WriteString(cell)
			if i < cols-1 {
				b.WriteString(strings.Repeat(" ", widths[i]-len(cell)+1))
			}
		}
		fmt.Fprintln(out, b.String())
	}
}

// listSheets writes the cheatsheet table.
func listSheets(sheets []Sheet, brief bool, out io.Writer) {
	w := &tabWriter{}
	if brief {
		w.add("title:", "tags:")
	} else {
		w.add("title:", "file:", "tags:")
	}
	for _, sheet := range sheets {
		if brief {
			w.add(sheet.Title, strings.Join(sheet.Tags, ","))
		} else {
			w.add(sheet.Title, sheet.File, strings.Join(sheet.Tags, ","))
		}
	}
	w.WriteTo(out)
}

// listDirectories writes the cheatpath table.
func listDirectories(conf *Config, out io.Writer) {
	w := &tabWriter{}
	for _, path := range conf.Cheatpaths {
		w.add(path.Name+":", path.Path)
	}
	w.WriteTo(out)
}

// allTags returns the sorted, de-duplicated set of tags in use.
