{"command": "cd /workspace && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

const version = "5.1.0"

const longDescription = `cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.`

const examples = `  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
    cheat tar

  To edit (or create) the foo cheatsheet:
    cheat -e foo

  To edit (or create) the foo/bar cheatsheet on the "work" cheatpath:
    cheat -p work -e foo/bar

  To view all cheatsheet directories:
    cheat -d

  To list all available cheatsheets:
    cheat -l

  To briefly list all cheatsheets whose titles match "apt":
    cheat -b apt

  To list all tags in use:
    cheat -T

  To list available cheatsheets that are tagged as "personal":
    cheat -l -t personal

  To search for "ssh" among all cheatsheets, and colorize matches:
    cheat -c -s ssh

  To search (by regex) for cheatsheets that contain an IP address:
    cheat -c -r -s '(?:[0-9]{1,3}\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash`

type options struct {
	fs          *FlagSet
	all         bool
	brief       bool
	colorize    bool
	completion  string
	conf        bool
	directories bool
	edit        string
	help        bool
	init        bool
	list        bool
	path        string
	regex       bool
	remove      string
	search      string
	tag         string
	tags        bool
	update      bool
	version     bool
	args        []string
}

// newOptions builds the flag set used by the program.
func newOptions() *options {
	fs := NewFlagSet()
	o := &options{fs: fs}
	fs.Bool("all", "a", "Search among all cheatpaths")
	fs.Bool("brief", "b", "List cheatsheets without file paths")
	fs.Bool("colorize", "c", "Colorize output")
	fs.String("completion", "", "Generate shell completion script (`shell`: bash, zsh, fish, powershell)")
	fs.Bool("conf", "", "Display the config file path")
	fs.Bool("directories", "d", "List cheatsheet directories")
	fs.String("edit", "e", "Edit `cheatsheet`")
	fs.Bool("help", "h", "help for cheat")
	fs.Bool("init", "", "Write a default config file to stdout")
	fs.Bool("list", "l", "List cheatsheets")
	fs.String("path", "p", "Return only sheets found on cheatpath `name`")
	fs.Bool("regex", "r", "Treat search <phrase> as a regex")
	fs.String("rm", "", "Remove (delete) `cheatsheet`")
	fs.String("search", "s", "Search cheatsheets for `phrase`")
	fs.String("tag", "t", "Return only sheets matching `tag`")
	fs.Bool("tags", "T", "List all tags in use")
	fs.Bool("update", "u", "Update git-backed cheatpaths")
	fs.Bool("version", "v", "Print the version number")
	return o
}

// helpText renders the usage message.
func helpText() string {
	o := newOptions()
	var b strings.Builder
	b.WriteString(longDescription)
	b.WriteString("\n\nUsage:\n  cheat [cheatsheet] [flags]\n\nExamples:\n")
	b.WriteString(examples)
	b.WriteString("\n\nFlags:\n")
	b.WriteString(o.fs.Usages())
	return b.String()
}

func fail(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}

func main() {
	if len(os.Args) > 1 && (os.Args[1] == "__complete" || os.Args[1] == "__completeNoDesc") {
		complete(os.Args[2:], os.Args[1] == "__completeNoDesc")
		return
	}

	o := newOptions()
	args, err := o.fs.Parse(os.Args[1:])
	if err != nil {
		fail("%s", err)
	}
	o.args = args

	o.all = o.fs.BoolValue("all")
	o.brief = o.fs.BoolValue("brief")
	o.colorize = o.fs.BoolValue("colorize")
	o.completion = o.fs.Value("completion")
	o.conf = o.fs.BoolValue("conf")
	o.directories = o.fs.BoolValue("directories")
	o.edit = o.fs.Value("edit")
	o.help = o.fs.BoolValue("help")
	o.init = o.fs.BoolValue("init")
	o.list = o.fs.BoolValue("list")
	o.path = o.fs.Value("path")
	o.regex = o.fs.BoolValue("regex")
	o.remove = o.fs.Value("rm")
	o.search = o.fs.Value("search")
	o.tag = o.fs.Value("tag")
	o.tags = o.fs.BoolValue("tags")
	o.update = o.fs.BoolValue("update")
	o.version = o.fs.BoolValue("version")

	// options that do not require a configuration file
	switch {
	case o.help:
		fmt.Print(helpText())
		return
	case o.version:
		fmt.Println(version)
		return
	case o.init:
		fmt.Println(initConfig(defaultConfigPath()))
		return
	case o.completion != "":
		if err := writeCompletion(o.completion); err != nil {
			fail("%s", err)
		}
		return
	}

	// locate the configuration file, running the installer if necessary
	confPath := locateConfig()
	if confPath == "" {
		ok, err := prompt("A config file was not found. Would you like to create one now? [Y/n]: ")
		if err != nil {
			fail("failed to create config: failed to prompt: %s", err)
		}
		if !ok {
			os.Exit(0)
		}
		if err := runInstaller(defaultConfigPath()); err != nil {
			fail("failed to run installer: %s", err)
		}
		os.Exit(0)
	}

	conf, err := Load(confPath)
	if err != nil {
		fail("failed to load config: %s", err)
	}
	if err := conf.withCwdPath(); err != nil {
		fail("failed to load config: %s", err)
	}

	// validate the --path option
	if o.path != "" {
		found := false
		for _, path := range conf.Cheatpaths {
			if path.Name == o.path {
				found = true
				break
			}
		}
		if !found {
			fail("invalid option --path: cheatpath does not exist: %s", o.path)
		}
	}

	colorize := o.colorize || (conf.Colorize && isTerminal(os.Stdout))

	switch {
	case o.conf:
		fmt.Println(conf.Path)
	case o.directories:
		display(conf, listDirectories(conf, os.Stdout))
	case o.edit != "":
		if err := editSheet(conf, o, o.edit); err != nil {
			fail("failed to edit cheatsheet: %s", err)
		}
	case o.list || o.brief:
		display(conf, func(w *pager) {
			sheets, err := loadSheets(conf)
			if err != nil {
				fail("failed to list cheatsheets: %s", err)
			}
			sheets = filterSheets(sheets, o.path, o.tag)
			sheets = filterTitles(sheets, firstArg(o.args))
			if len(sheets) == 0 {
				os.Exit(2)
			}
			listSheets(sheets, o.brief, w)
		})
	case o.tags:
		display(conf, func(w *pager) {
			sheets, err := loadSheets(conf)
			if err != nil {
				fail("failed to list tags: %s", err)
			}
			tags := collectTags(sheets)
			if len(tags) == 0 {
				return
			}
			for _, tag := range tags {
				fmt.Fprintln(w, tag)
			}
		})
	case o.update:
		if err := updateCheatpaths(conf, o.path); err != nil {
			os.Exit(1)
		}
	case o.search != "":
		display(conf, func(w *pager) {
			sheets, err := loadSheets(conf)
			if err != nil {
				fail("failed to search cheatsheets: %s", err)
			}
			sheets = filterSheets(sheets, o.path, o.tag)
			blocks, err := searchSheets(sheets, o.search, o.regex, colorize)
			if err != nil {
				fail("failed to search cheatsheets: %s", err)
			}
			if len(blocks) == 0 {
				return
			}
			fmt.Fprint(w, strings.Join(blocks, "\n\n"))
		})
	case o.remove != "":
		if err := removeSheet(conf, o, o.remove); err != nil {
			if err == errNotFound {
				fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", o.remove)
				os.Exit(2)
			}
			fail("%s", err)
		}
	case len(o.args) > 0:
		title := o.args[0]
		if err := showSheet(conf, o, title, colorize); err != nil {
			if err == errNotFound {
				fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
				os.Exit(2)
			}
			fail("%s", err)
		}
	case o.tag != "":
		display(conf, func(w *pager) {
			sheets, err := loadSheets(conf)
			if err != nil {
				fail("failed to list cheatsheets: %s", err)
			}
			sheets = filterSheets(sheets, o.path, o.tag)
			if len(sheets) == 0 {
				os.Exit(2)
			}
			listSheets(sheets, false, w)
		})
	default:
		fmt.Print(helpText())
	}
}

func firstArg(args []string) string {
	if len(args) == 0 {
		return ""
	}
	return args[0]
}

// display runs fn with a writer that is piped through the configured pager.
func display(conf *Config, fn func(w *pager)) {
	w := newPager(conf)
	fn(w)
	if err := w.close(); err != nil {
		fail("failed to write to pager: %s", err)
	}
}

// collectTags returns the sorted, de-duplicated tags in use.
func collectTags(sheets []Sheet) []string {
	seen := map[string]bool{}
	var tags []string
	for _, sheet := range sheets {
		for _, tag := range sheet.Tags {
			if !seen[tag] {
				seen[tag] = true
				tags = append(tags, tag)
			}
		}
	}
	sort.Strings(tags)
	return tags
}
EOF
gofmt -l main.go; echo ok"}

