		if err := removeSheet(conf, o, o.remove); err != nil {
			if err == errNotFound {
				fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", o.remove)
				os.Exit(2)
			}
			fail("%s", err)
		}
	case len(o.args) > 0:
		title := o.args[0]
		if err := showSheet(conf, o, title, colorize); err != nil {
			if err == errNotFound {
				fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
				os.Exit(2)
			}
			fail("%s", err)
		}
	case o.tag != "":
		display(conf, func(w *pager) {
			sheets, err := loadSheets(conf)
			if err != nil {
				fail("failed to list cheatsheets: %s", err)
			}
			sheets = filterSheets(sheets, o.path, o.tag)
			if len(sheets) == 0 {
				os.Exit(2)
			}
			listSheets(sheets, false, w)
		})
	default:
		fmt.Print(helpText())
	}
}

func firstArg(args []string) string {
	if len(args) == 0 {
		return ""
	}
	return args[0]
}

// display runs fn with a writer that is piped through the configured pager.
func display(conf *Config, fn func(w *pager)) {
	w := newPager(conf)
	fn(w)
	if err := w.close(); err != nil {
		fail("failed to write to pager: %s", err)
	}
}

