package main

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"unsafe"
)

// isTerminal reports whether the given file is attached to a terminal.
func isTerminal(f *os.File) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), syscall.TCGETS,
		uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

// pager writes its output either to stdout or through an external pager.
type pager struct {
	conf   *Config
	cmd    *exec.Cmd
	pipe   io.WriteCloser
	stdout io.Writer
	err    error
}

func newPager(conf *Config) *pager {
	p := &pager{conf: conf, stdout: os.Stdout}
	words := strings.Fields(conf.Pager)
	if len(words) == 0 {
		return p
	}
	cmd := exec.Command(words[0], words[1:]...)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		p.err = err
		return p
	}
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		p.err = err
		return p
	}
	p.cmd = cmd
	p.pipe = stdin
	return p
}

func (p *pager) Write(b []byte) (int, error) {
	if p.pipe != nil {
		return p.pipe.Write(b)
	}
	return p.stdout.Write(b)
}

// close flushes and waits for the pager to exit.
func (p *pager) close() error {
	if p.err != nil {
		return p.err
	}
	if p.pipe == nil {
		return nil
	}
	if err := p.pipe.Close(); err != nil {
		return err
	}
	return p.cmd.Wait()
}

// writeOut writes text to stdout, honouring the configured pager.
func writeOut(conf *Config, text string) error {
	p := newPager(conf)
	if p.err != nil {
		return p.err
	}
	if _, err := io.WriteString(p, text); err != nil {
		p.close()
		return err
	}
	return p.close()
}

// debug helper used during development
var _ = fmt.Sprintf
EOF
gofmt -l pager.go; echo ok"}

