func showSheet(conf *Config, o *options, title string, colorize bool) error {
	sheets, err := loadSheets(conf)
	if err != nil {
		fail("failed to list cheatsheets: %s", err)
	}
	sheets = filterSheets(sheets, o.path, o.tag)
	var matches []Sheet
	for _, sheet := range sheets {
		if sheet.Title == title {
			matches = append(matches, sheet)
		}
	}
	if len(matches) == 0 {
		return errNotFound
	}
	if o.all {
		var blocks []string
		for _, sheet := range matches {
			blocks = append(blocks, sheetBlock(sheet, sheet.Text, colorize))
		}
		return writeOut(conf, strings.Join(blocks, "\n\n")+"\n")
	}
	sheet := matches[len(matches)-1]
	text := sheet.Text
	if colorize {
		text = highlight(text, sheet.Syntax, conf)
	}
	return writeOut(conf, text)
}

// sheetBlock renders a single cheatsheet in the search/listing style.
func sheetBlock(sheet Sheet, text string, colorize bool) string {
	var b strings.Builder
	b.WriteString(sheet.Title)
	b.WriteString(" ")
	if colorize {
		b.WriteString("\x1b[2m(" + sheet.Path.Name + ")\x1b[0m")
	} else {
		b.WriteString("(" + sheet.Path.Name + ")")
	}
	b.WriteString("\n")
	hl := text
	if colorize {
		hl = highlight(text, sheet.Syntax, colorizeStyle(sheet))
	}
	b.WriteString(indent(hl))
	return b.String()
}

func indent(s string) string {
	return "\t" + strings.ReplaceAll(s, "\n", "\n\t")
}

// searchSheets renders the blocks for all sheets matching the phrase.
func searchSheets(sheets []Sheet, phrase string, regex, colorize bool) ([]string, error) {
	var find func(text string) []int
	var matches func(text string) bool
	if regex {
		re, err := regexp.Compile(phrase)
		if err != nil {
			return nil, fmt.Errorf("failed to compile regexp: %s, %s", phrase, err)
		}
		matches = func(text string) bool { return re.MatchString(text) }
		find = func(text string) []int {
			var out []int
			for _, loc := range re.FindAllStringIndex(text, -1) {
				out = append(out, loc[0], loc[1])
			}
			return out
		}
	} else {
		lower := strings.ToLower(phrase)
		matches = func(text string) bool {
			return strings.Contains(strings.ToLower(text), lower)
		}
		find = func(text string) []int {
			hay := strings.ToLower(text)
			var out []int
			start := 0
			for {
				idx := strings.Index(hay[start:], lower)
				if idx < 0 {
					break
				}
				out = append(out, start+idx, start+idx+len(lower))
				start += idx + len(lower)
			}
			return out
		}
	}
	var blocks []string
	for _, sheet := range sheets {
		if !matches(sheet.Text) {
			continue
		}
		text := paragraph(sheet.Text, find(sheet.Text))
		blocks = append(blocks, sheetBlock(sheet, text, colorize))
	}
	return blocks, nil
}

// paragraph extracts the paragraph(s) that surround the matches.
func paragraph(text string, positions []int) string {
	if len(positions) == 0 {
		return text
	}
	lines := lineOffsets(text)
	first, last := positions[0], positions[len(positions)-1]
	startLine, endLine := 0, len(lines)-1
	for i, off := range lines {
		if off > first {
			startLine = i - 1
			break
		}
		if off == first {
			startLine = i
		}
	}
	for i, off := range lines {
		if off > last {
			endLine = i - 1
			break
		}
		if off == last {
			endLine = i
		}
	}
	// expand to the surrounding paragraph boundaries
	for startLine > 0 && strings.TrimRight(lineAt(text, lines, startLine-1), "\r") != "" {
		startLine--
	}
	for endLine < len(lines)-1 && strings.TrimRight(lineAt(text, lines, endLine+1), "\r") != "" {
		endLine++
	}
	start := lines[startLine]
	end := len(text)
	if endLine+1 < len(lines) {
		end = lines[endLine+1] - 1
	}
	if end < start {
		end = start
	}
	return text[start:end]
}

// lineOffsets returns the byte offset at which each line of text begins.
func lineOffsets(text string) []int {
	offsets := []int{0}
	for i := 0; i < len(text); i++ {
		if text[i] == '\n' {
			offsets = append(offsets, i+1)
		}
	}
	return offsets
}

func lineAt(text string, offsets []int, n int) string {
	start := offsets[n]
	end := len(text)
	if n+1 < len(offsets) {
		end = offsets[n+1] - 1
	}
	return text[start:end]
}

var _ io.Writer = os.Stdout
EOF
gofmt -l actions.go; echo ok"}

