{"command": "cd /workspace && cat > highlight.go <<'EOF'
package main

import (
	"strings"
)

// tokenKind enumerates the token classes emitted by the highlighter.
type tokenKind int

const (
	tkText tokenKind = iota
	tkWhitespace
	tkPunctuation
	tkComment
	tkKeyword
	tkKeywordNamespace
	tkOperator
	tkString
	tkStringEscape
	tkNumber
	tkNameFunction
	tkNameDecorator
	tkNameTag
	tkNameBuiltin
	tkName
	tkError
	tkHeading
	tkEmph
	tkStrong
	tkDeleted
	tkInserted
	tkOutput
)

// styleEntry describes how a token class is rendered.
type styleEntry struct {
	fg        string // hex colour, without '#'
	bg        string
	bold      bool
	italic    bool
	underline bool
	zero      bool
}

// monokai reproduces the colours of the monokai colourscheme.
var monokai = map[tokenKind]styleEntry{
	tkText:            {fg: "f8f8f2"},
	tkWhitespace:      {fg: "f8f8f2"},
	tkPunctuation:     {fg: "f8f8f2"},
	tkName:            {fg: "f8f8f2"},
	tkNameBuiltin:     {fg: "f8f8f2"},
	tkComment:         {fg: "75715e"},
	tkKeyword:         {fg: "66d9ef"},
	tkKeywordNamespace: {fg: "f92672"},
	tkOperator:        {fg: "f92672"},
	tkString:          {fg: "e6db74"},
	tkStringEscape:    {fg: "ae81ff"},
	tkNumber:          {fg: "ae81ff"},
	tkNameFunction:    {fg: "a6e22e"},
	tkNameDecorator:   {fg: "a6e22e"},
	tkNameTag:         {fg: "f92672"},
	tkError:           {fg: "960050", bg: "1e0010"},
	tkHeading:         {fg: "f8f8f2"},
	tkEmph:            {fg: "f8f8f2", italic: true},
	tkStrong:          {fg: "f8f8f2", bold: true},
	tkDeleted:         {fg: "f92672"},
	tkInserted:        {fg: "a6e22e"},
	tkOutput:          {fg: "888888"},
}

// ansi256For maps the colours used by the supported styles to their ANSI-256
// palette indices.
var ansi256For = map[string]int{
	"f8f8f2": 231,
	"e6db74": 186,
	"75715e": 242,
	"66d9ef": 81,
	"f92672": 197,
	"a6e22e": 148,
	"ae81ff": 141,
	"960050": 89,
	"1e0010": 232,
	"888888": 102,
	"ffffff": 231,
	"e5e5e5": 255,
	"00ffff": 51,
	"007f7f": 6,
	"ff5faf": 213,
}

// entry resolves the style entry for a token kind, walking up the (implicit)
// hierarchy.
func entry(kind tokenKind) styleEntry {
	if e, ok := monokai[kind]; ok {
		return e
	}
	switch kind {
	case tkNameFunction, tkNameDecorator, tkNameTag, tkNameBuiltin, tkName:
		return monokai[tkName]
	case tkKeywordNamespace:
		return monokai[tkKeyword]
	case tkStringEscape:
		return monokai[tkString]
	}
	return styleEntry{zero: true}
}

func hexToRGB(h string) (int, int, int, bool) {
	if len(h) != 6 {
		return 0, 0, 0, false
	}
	var vals [3]int
	for i := 0; i < 3; i++ {
		v := 0
		for j := 0; j < 2; j++ {
			c := h[i*2+j]
			var d int
			switch {
			case c >= '0' && c <= '9':
				d = int(c - '0')
			case c >= 'a' && c <= 'f':
				d = int(c-'a') + 10
			case c >= 'A' && c <= 'F':
				d = int(c-'A') + 10
			default:
				return 0, 0, 0, false
			}
			v = v*16 + d
		}
		vals[i] = v
	}
	return vals[0], vals[1], vals[2], true
}

// escapeSequence builds the ANSI escape sequence for a style entry.
func escapeSequence(e styleEntry, formatter string) string {
	if e.zero {
		return ""
	}
	var b strings.Builder
	if e.bold {
		b.WriteString("\x1b[1m")
	}
	if e.italic {
		b.WriteString("\x1b[3m")
	}
	if e.underline {
		b.WriteString("\x1b[4m")
	}
	if e.fg != "" {
		switch formatter {
		case "terminal16m":
			r, g, bl, ok := hexToRGB(e.fg)
			if ok {
				b.WriteString("\x1b[38;2;" + itoa(r) + ";" + itoa(g) + ";" + itoa(bl) + "m")
			}
		default:
			if idx, ok := ansi256For[e.fg]; ok {
				b.WriteString("\x1b[38;5;" + itoa(idx) + "m")
			}
		}
	}
	if e.bg != "" {
		switch formatter {
		case "terminal16m":
			r, g, bl, ok := hexToRGB(e.bg)
			if ok {
				b.WriteString("\x1b[48;2;" + itoa(r) + ";" + itoa(g) + ";" + itoa(bl) + "m")
			}
		default:
			if idx, ok := ansi256For[e.bg]; ok {
				b.WriteString("\x1b[48;5;" + itoa(idx) + "m")
			}
		}
	}
	return b.String()
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var buf [8]byte
	pos := len(buf)
	for i > 0 {
		pos--
		buf[pos] = byte('0' + i%10)
		i /= 10
	}
	return string(buf[pos:])
}

// token is a lexed unit of text.
type token struct {
	kind  tokenKind
	value string
}

// highlight renders text with the configured colours.
func highlight(text, syntax string, conf *Config) string {
	lexer := lookupLexer(syntax)
	if lexer == nil {
		lexer = detectLexer(text)
	}
	tokens := lexer(text)
	formatter := conf.Formatter
	if formatter == "" {
		formatter = "terminal"
	}
	var b strings.Builder
	for _, tok := range tokens {
		e := entry(tok.kind)
		seq := escapeSequence(e, formatter)
		parts := strings.Split(tok.value, "\n")
		if len(parts) > 1 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
		for i, part := range parts {
			b.WriteString(seq)
			b.WriteString(part)
			if seq != "" {
				b.WriteString("\x1b[0m")
			}
			if i < len(parts)-1 {
				b.WriteString("\n")
			}
		}
		if strings.HasSuffix(tok.value, "\n") {
			b.WriteString("\n")
		}
	}
	return b.String()
}
EOF
gofmt -w highlight.go; echo ok"}

