// escapeSequence builds the ANSI escape sequence for a style entry.
func escapeSequence(e styleEntry, formatter string) string {
	if e.zero {
		return ""
	}
	var b strings.Builder
	if e.bold {
		b.WriteString("\x1b[1m")
	}
	if e.italic {
		b.WriteString("\x1b[3m")
	}
	if e.underline {
		b.WriteString("\x1b[4m")
	}
	if e.fg != "" {
		switch formatter {
		case "terminal16m":
			r, g, bl, ok := hexToRGB(e.fg)
			if ok {
				b.WriteString("\x1b[38;2;" + itoa(r) + ";" + itoa(g) + ";" + itoa(bl) + "m")
			}
		default:
			if idx, ok := ansi256For[e.fg]; ok {
				b.WriteString("\x1b[38;5;" + itoa(idx) + "m")
			}
		}
	}
	if e.bg != "" {
		switch formatter {
		case "terminal16m":
			r, g, bl, ok := hexToRGB(e.bg)
			if ok {
