			}
		}
	}
	return b.String()
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var buf [8]byte
	pos := len(buf)
	for i > 0 {
		pos--
		buf[pos] = byte('0' + i%10)
		i /= 10
	}
	return string(buf[pos:])
}

// token is a lexed unit of text.
type token struct {
	kind  tokenKind
	value string
}

// highlight renders text with the configured colours.
func highlight(text, syntax string, conf *Config) string {
	lexer := lookupLexer(syntax)
	if lexer == nil {
		lexer = detectLexer(text)
	}
	tokens := lexer(text)
	formatter := conf.Formatter
	if formatter == "" {
		formatter = "terminal"
	}
	var b strings.Builder
	for _, tok := range tokens {
		e := entry(tok.kind)
		seq := escapeSequence(e, formatter)
		parts := strings.Split(tok.value, "\n")
		if len(parts) > 1 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
		for i, part := range parts {
			b.WriteString(seq)
			b.WriteString(part)
			if seq != "" {
				b.WriteString("\x1b[0m")
			}
			if i < len(parts)-1 {
				b.WriteString("\n")
			}
		}
		if strings.HasSuffix(tok.value, "\n") {
			b.WriteString("\n")
		}
	}
	return b.String()
}
