package main

import "strings"

// lexerFunc tokenizes text into a sequence of tokens.
type lexerFunc func(string) []token

var shellKeywords = map[string]bool{
	"if": true, "then": true, "else": true, "elif": true, "fi": true,
	"for": true, "while": true, "until": true, "do": true, "done": true,
	"case": true, "esac": true, "function": true, "select": true,
	"return": true, "continue": true, "break": true, "time": true,
	"coproc": true, "[[": true, "]]": true, "in": true,
}

var shellBuiltins = map[string]bool{
	"echo": true, "cd": true, "eval": true, "exec": true, "exit": true,
	"export": true, "set": true, "unset": true, "readonly": true,
	"local": true, "declare": true, "typeset": true, "shift": true,
	"trap": true, "source": true, "alias": true, "bind": true,
	"builtin": true, "caller": true, "command": true, "compgen": true,
	"complete": true, "dirs": true, "disown": true, "enable": true,
	"fg": true, "getopts": true, "hash": true, "help": true,
	"history": true, "jobs": true, "kill": true, "let": true,
	"logout": true, "popd": true, "printf": true, "pushd": true,
	"pwd": true, "read": true, "shopt": true, "suspend": true,
	"test": true, "type": true, "ulimit": true, "umask": true,
	"unalias": true, "wait": true, "bg": true, "true": true,
	"false": true, "test": true, "time": true, "pushd": true,
	"popd": true, "readonly": true, "mapfile": true, "readarray": true,
	"fc": true, "fc": true, "fc": true,
}

// plaintextLexer emits one token per line, including the line break.
func plaintextLexer(text string) []token {
	var tokens []token
	for _, line := range strings.SplitAfter(text, "\n") {
		if line == "" {
			continue
		}
		tokens = append(tokens, token{kind: tkText, value: line})
	}
	return tokens
}

func isWordChar(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func isNameStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

// shellLexer tokenizes POSIX-shell-like input.
func shellLexer(text string) []token {
	var tokens []token
	var run strings.Builder
	flush := func() {
		if run.Len() > 0 {
			tokens = append(tokens, token{kind: tkText, value: run.String()})
			run.Reset()
		}
	}
	i := 0
	n := len(text)
	wordStart := true
	for i < n {
		c := text[i]
		// comments begin only at the start of a word
		if c == '#' && wordStart {
			flush()
			j := i
			for j < n && text[j] != '\n' {
				j++
			}
			tokens = append(tokens, token{kind: tkComment, value: text[i:j]})
			i = j
			wordStart = true
			continue
		}
		// words: keywords, builtins and plain words
		if isNameStart(c) && wordStart {
			j := i
			for j < n && isWordChar(text[j]) {
				j++
			}
			word := text[i:j]
			switch {
			case shellKeywords[word]:
				flush()
				tokens = append(tokens, token{kind: tkKeyword, value: word})
			case shellBuiltins[word]:
				flush()
				tokens = append(tokens, token{kind: tkNameBuiltin, value: word})
			default:
				run.WriteString(word)
			}
			i = j
			wordStart = false
			continue
		}
		// numbers
		if c >= '0' && c <= '9' && wordStart {
			j := i
			for j < n && text[j] >= '0' && text[j] <= '9' {
				j++
			}
			if j >= n || !(text[j] == '.' || isWordChar(text[j])) {
				flush()
				tokens = append(tokens, token{kind: tkNumber, value: text[i:j]})
				i = j
				wordStart = false
				continue
			}
		}
		switch c {
		case ' ', '\t', '\n', '\r':
			run.WriteByte(c)
			i++
			wordStart = true
			continue
		case '"':
			flush()
			tok, next := lexDoubleQuoted(text, i)
			tokens = append(tokens, tok...)
			i = next
			wordStart = false
			continue
		case '\'':
			flush()
			tok, next := lexSingleQuoted(text, i)
			tokens = append(tokens, tok...)
			i = next
			wordStart = false
			continue
		case '`':
			flush()
			j := i + 1
			for j < n && text[j] != '`' {
				j++
			}
			if j < n {
				j++
			}
			tokens = append(tokens, token{kind: tkString, value: text[i:j]})
			i = j
			wordStart = false
			continue
		case '$':
			flush()
			tok, next := lexVariable(text, i)
			tokens = append(tokens, tok...)
			i = next
			wordStart = false
			continue
		case '\\':
			flush()
			if i+1 < n {
				tokens = append(tokens, token{kind: tkStringEscape, value: text[i : i+2]})
				i += 2
			} else {
				tokens = append(tokens, token{kind: tkStringEscape, value: "\\"})
				i++
			}
			wordStart = false
			continue
		case '=':
			flush()
			tokens = append(tokens, token{kind: tkOperator, value: "="})
			i++
			wordStart = false
			continue
		case '(', ')', '{', '}', '[', ']':
			flush()
			tokens = append(tokens, token{kind: tkOperator, value: string(c)})
			i++
			wordStart = false
			continue
		case '|', '&':
			if i+1 < n && text[i+1] == c {
				flush()
				tokens = append(tokens, token{kind: tkOperator, value: text[i : i+2]})
				i += 2
				wordStart = false
				continue
			}
			flush()
			tokens = append(tokens, token{kind: tkText, value: string(c)})
			i++
			wordStart = false
			continue
		case ';':
			flush()
			j := i
			for j < n && text[j] == ';' {
				j++
			}
			kind := tkText
			if j-i > 1 {
				kind = tkOperator
			}
			tokens = append(tokens, token{kind: kind, value: text[i:j]})
			i = j
			wordStart = false
			continue
		}
		run.WriteByte(c)
		i++
		wordStart = false
	}
	flush()
	return tokens
}

// lexDoubleQuoted tokenizes a double-quoted string.
func lexDoubleQuoted(text string, i int) ([]token, int) {
	n := len(text)
	var tokens []token
	start := i
	j := i + 1
	for j < n {
		if text[j] == '\\' && j+1 < n {
			j += 2
			continue
		}
		if text[j] == '"' {
			j++
			break
		}
		j++
	}
	tokens = append(tokens, token{kind: tkString, value: text[start:j]})
	return tokens, j
}

// lexSingleQuoted tokenizes a single-quoted string.
func lexSingleQuoted(text string, i int) ([]token, int) {
	n := len(text)
	j := i + 1
	for j < n {
		if text[j] == '\'' {
			j++
			return []token{{kind: tkString, value: text[i:j]}}, j
		}
		j++
	}
	return []token{{kind: tkError, value: "'"}}, i + 1
}

// lexVariable tokenizes a variable reference.
func lexVariable(text string, i int) ([]token, int) {
	n := len(text)
	if i+1 < n && text[i+1] == '{' {
		j := i + 2
		for j < n && text[j] != '}' {
			j++
		}
		if j < n {
			j++
		}
		return []token{
			{kind: tkString, value: "${"},
			{kind: tkText, value: text[i+2 : j-1]},
			{kind: tkString, value: "}"},
		}, j
	}
	if i+1 < n && text[i+1] == '(' {
		j := i + 2
		depth := 1
		for j < n && depth > 0 {
			switch text[j] {
			case '(':
				depth++
			case ')':
				depth--
			}
			j++
		}
		return []token{{kind: tkString, value: text[i:j]}}, j
	}
	j := i + 1
	if j < n && (isNameStart(text[j]) || text[j] == '?' || text[j] == '@' || text[j] == '#' || text[j] == '!' || text[j] == '-' || text[j] == '*' || (text[j] >= '0' && text[j] <= '9')) {
		j++
		for j < n && isWordChar(text[j]) {
			j++
		}
	}
	if j == i+1 {
		return []token{{kind: tkText, value: "$"}}, j
	}
	return []token{{kind: tkName, value: text[i:j]}}, j
}

// detectLexer picks the lexer to use for text without an explicit syntax.
func detectLexer(text string) lexerFunc {
	if sameTokens(shellLexer(text), plaintextLexer(text)) {
		return plaintextLexer
	}
	return shellLexer
}

func sameTokens(a, b []token) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].kind != b[i].kind || a[i].value != b[i].value {
			return false
		}
	}
	return true
}

// lookupLexer resolves a syntax name to a lexer.
func lookupLexer(syntax string) lexerFunc {
	switch strings.ToLower(strings.TrimSpace(syntax)) {
	case "", "plaintext", "text", "txt":
		return nil
	case "bash", "sh", "shell", "zsh", "ksh":
		return shellLexer
	}
	return nil
}
EOF
gofmt -w lexers.go && go build ./... 2>&1 | head"}

