	start := i
	j := i + 1
	for j < n {
		if text[j] == '\\' && j+1 < n {
			j += 2
			continue
		}
		if text[j] == '"' {
			j++
			break
		}
		j++
	}
	tokens = append(tokens, token{kind: tkString, value: text[start:j]})
	return tokens, j
}

// lexSingleQuoted tokenizes a single-quoted string.
func lexSingleQuoted(text string, i int) ([]token, int) {
	n := len(text)
	j := i + 1
	for j < n {
		if text[j] == '\'' {
			j++
			return []token{{kind: tkString, value: text[i:j]}}, j
		}
		j++
	}
	return []token{{kind: tkError, value: "'"}}, i + 1
}

// lexVariable tokenizes a variable reference.
func lexVariable(text string, i int) ([]token, int) {
	n := len(text)
	if i+1 < n && text[i+1] == '{' {
		j := i + 2
		for j < n && text[j] != '}' {
			j++
		}
		if j < n {
			j++
		}
		return []token{
			{kind: tkString, value: "${"},
			{kind: tkText, value: text[i+2 : j-1]},
			{kind: tkString, value: "}"},
		}, j
	}
	if i+1 < n && text[i+1] == '(' {
		j := i + 2
		depth := 1
		for j < n && depth > 0 {
			switch text[j] {
			case '(':
				depth++
			case ')':
				depth--
			}
			j++
		}
		return []token{{kind: tkString, value: text[i:j]}}, j
	}
	j := i + 1
	if j < n && (isNameStart(text[j]) || text[j] == '?' || text[j] == '@' || text[j] == '#' || text[j] == '!' || text[j] == '-' || text[j] == '*' || (text[j] >= '0' && text[j] <= '9')) {
		j++
		for j < n && isWordChar(text[j]) {
			j++
		}
	}
