func stripYamlComment(s string) string {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case c == '#' && !inSingle && !inDouble && (i == 0 || s[i-1] == ' ' || s[i-1] == '\\t'):
			return strings.TrimRight(s[:i], " \\t")
		}
	}
	return strings.TrimRight(s, " \\t")
}

func (p *yamlParser) peek() (yamlLine, bool) {
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.content != "" {
			return l, true
		}
		p.pos++
	}
	return yamlLine{}, false
}

func (p *yamlParser) isSeqEntry(l yamlLine) bool {
	if l.content == "-" {
		return true
	}
	return strings.HasPrefix(l.content, "- ") || strings.HasPrefix(l.content, "-\\t")
}

// parseDocument parses the whole document and returns the root node.
func (p *yamlParser) parseDocument() (*yamlNode, error) {
	l, ok := p.peek()
	if !ok {
		return nil, nil
	}
	return p.parseNode(l.indent)
}

// parseNode parses a block node whose entries are indented at least indent.
func (p *yamlParser) parseNode(indent int) (*yamlNode, error) {
	l, ok := p.peek()
	if !ok || l.indent < indent {
		return nil, nil
	}
	if p.isSeqEntry(l) {
		return p.parseSeq(l.indent)
	}
	return p.parseMap(l.indent)
}

func (p *yamlParser) parseSeq(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, tag: "!!seq"}
	first := true
	for {
		l, ok := p.peek()
		if !ok || l.indent != indent || !p.isSeqEntry(l) {
			break
		}
		if first {
			node.line = l.num
			first = false
		}
		rest := strings.TrimLeft(l.content[1:], " \\t")
		off := len(l.content) - len(rest)
		lineNum := l.num
		if rest == "" {
			p.pos++
			child, err := p.parseNode(indent + 1)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = &yamlNode{kind: yamlScalar, tag: "!!null", line: lineNum}
			}
			node.seq = append(node.seq, child)
			continue
		}
		// rewrite the line so that the entry content starts at its own column
		p.lines[p.pos] = yamlLine{
			indent:  indent + off,
			content: rest,
			raw:     strings.Repeat(" ", indent+off) + rest,
			num:     lineNum,
		}
		child, err := p.parseNode(indent + off)
		if err != nil {
			return nil, err
		}
		if child == nil {
			child = &yamlNode{kind: yamlScalar, tag: "!!null", line: lineNum}
		}
		node.seq = append(node.seq, child)
	}
	if len(node.seq) == 0 {
		return nil, nil
	}
	return node, nil
