// parseScalarNode parses a scalar document, joining continuation lines.
func (p *yamlParser) parseScalarNode(l yamlLine) (*yamlNode, error) {
	text := l.content
	p.pos++
	for {
		nl, ok := p.peek()
		if !ok || nl.indent <= l.indent {
			break
		}
		if key, _, err := splitMapKey(nl.content); err != nil || key != "" {
			break
		}
