start = src.index("// Decoder helpers ---")
new = '''// Decoder helpers -----------------------------------------------------------

type decoder struct {
	errs typeErrors
}

func (d *decoder) err(n *yamlNode, typ string) {
	if n == nil {
		n = &yamlNode{tag: "!!null"}
	}
	d.errs = append(d.errs, UnmarshalError{Line: n.line, Type: typ, Tag: n.tag, Value: n.value})
}

// decodeString decodes a node into a string, mirroring the permissiveness of
// the original implementation.
func (d *decoder) decodeString(n *yamlNode, typ string) string {
	if n == nil {
		return ""
	}
	if n.kind != yamlScalar {
		d.err(n, typ)
		return ""
	}
	if n.tag == "!!null" {
		return ""
	}
	return n.value
}

// decodeBool decodes a node into a bool.
func (d *decoder) decodeBool(n *yamlNode, typ string) bool {
	if n == nil {
		return false
	}
	if n.kind != yamlScalar {
		d.err(n, typ)
		return false
	}
	if n.tag == "!!null" {
		return false
	}
	if v, ok := n.Bool(); ok {
		return v
	}
	d.err(n, typ)
	return false
}

// decodeStringSlice decodes a node into a []string.
func (d *decoder) decodeStringSlice(n *yamlNode, typ string) []string {
	if n == nil {
		return nil
	}
	if n.kind != yamlSequence {
		if n.kind == yamlScalar && n.tag == "!!null" {
			return nil
		}
		d.err(n, typ)
		return nil
	}
	var out []string
	for _, child := range n.seq {
		out = append(out, d.decodeString(child, "string"))
	}
	return out
}

// decodeCheatpaths decodes the cheatpaths section.
func (d *decoder) decodeCheatpaths(n *yamlNode) []Cheatpath {
	if n == nil {
		return nil
	}
	if n.kind != yamlSequence {
		if n.kind == yamlScalar && n.tag == "!!null" {
			return nil
		}
		d.err(n, "[]cheatpath.Path")
		return nil
	}
	var out []Cheatpath
	for _, child := range n.seq {
		cp := Cheatpath{}
		if child.kind != yamlMapping {
			if child.kind == yamlScalar && child.tag == "!!null" {
				out = append(out, cp)
				continue
			}
			d.err(child, "cheatpath.Path")
			continue
		}
		for i, key := range child.keys {
			val := child.vals[i]
			switch strings.ToLower(key.value) {
			case "name":
				cp.Name = d.decodeString(val, "string")
			case "path":
				cp.Path = d.decodeString(val, "string")
			case "tags":
				cp.Tags = d.decodeStringSlice(val, "[]string")
			case "readonly":
				cp.Readonly = d.decodeBool(val, "bool")
			}
		}
		out = append(out, cp)
	}
	return out
}

// unmarshalErrors normalises a decoder error into the message the original
// implementation produces.
func unmarshalErrors(err error) error {
	return fmt.Errorf("could not unmarshal yaml: %s", err)
}
'''
