// paragraph extracts the paragraph(s) that surround the matches.
func paragraph(text string, positions []int) string {
	if len(positions) == 0 {
		return text
	}
	offsets := lineOffsets(text)
	first, last := positions[0], positions[len(positions)-1]
	startLine, endLine := 0, len(offsets)-1
	for i, off := range offsets {
		if off == first {
			startLine = i
			break
		}
		if off > first {
			startLine = i - 1
			break
		}
	}
	for i, off := range offsets {
		if off == last {
			endLine = i
			break
		}
		if off > last {
			endLine = i - 1
			break
		}
	}
	if startLine < 0 {
		startLine = 0
	}
	if endLine < 0 {
		endLine = 0
	}
	for startLine > 0 && strings.TrimRight(lineAt(text, offsets, startLine-1), "\\r") != "" {
		startLine--
	}
	for endLine < len(offsets)-1 && strings.TrimRight(lineAt(text, offsets, endLine+1), "\\r") != "" {
		endLine++
	}
	start := offsets[startLine]
	end := len(text)
	if endLine+1 < len(offsets) {
		end = offsets[endLine+1] - 1
	}
	if end < start {
		end = start
	}
	return text[start:end]
}

// lineOffsets returns the byte offset at which each line of text begins.
func lineOffsets(text string) []int {
	offsets := []int{0}
	for i := 0; i < len(text); i++ {
		if text[i] == '\\n' {
			offsets = append(offsets, i+1)
		}
	}
	return offsets
}

func lineAt(text string, offsets []int, n int) string {
	start := offsets[n]
	end := len(text)
	if n+1 < len(offsets) {
		end = offsets[n+1] - 1
	}
	return text[start:end]
}
