{"command": "cd /workspace && cat >> lexers.go <<'EOF'

var yamlBooleans = map[string]bool{
	"true": true, "True": true, "TRUE": true, "false": true, "False": true,
	"FALSE": true, "yes": true, "Yes": true, "YES": true, "no": true,
	"No": true, "NO": true, "on": true, "On": true, "ON": true, "off": true,
	"Off": true, "OFF": true, "y": true, "Y": true, "n": true, "N": true,
	"null": true, "Null": true, "NULL": true, "~": true,
}

// yamlLexer tokenizes YAML front-matter-like documents.
func yamlLexer(text string) []token {
	var tokens []token
	lines := strings.SplitAfter(text, "\n")
	for li := 0; li < len(lines); li++ {
		line := lines[li]
		if line == "" {
			continue
		}
		i := 0
		for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
			i++
		}
		if i > 0 {
			tokens = append(tokens, token{kind: tkText, value: line[:i]})
		}
		rest := line[i:]
		var nl string
		if strings.HasSuffix(rest, "\n") {
			nl = "\n"
			rest = rest[:len(rest)-1]
		}
		if rest == "" {
			if nl != "" {
				tokens = append(tokens, token{kind: tkText, value: nl})
			}
			continue
		}
		// a block scalar: the content of the following lines is a single string
		if rest == "|" || rest == ">" || strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
			if strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
				head := rest
				trimmed := strings.TrimRight(head, " \t+-")
				tail := head[len(trimmed):]
				if trimmed != "" {
					tokens = append(tokens, token{kind: tkPunctuation, value: trimmed})
				}
				if tail != "" {
					tokens = append(tokens, token{kind: tkPunctuation, value: tail})
				}
			}
			var body strings.Builder
			if nl != "" {
				body.WriteString(nl)
			}
			base := -1
			for li+1 < len(lines) {
				next := lines[li+1]
				trimmedNext := strings.TrimRight(next, "\n\r")
				if strings.TrimSpace(trimmedNext) == "" {
					break
				}
				ni := 0
				for ni < len(next) && (next[ni] == ' ' || next[ni] == '\t') {
					ni++
				}
				if ni <= i {
					break
				}
				if base < 0 {
					base = ni
				}
				chunk := next
				if len(chunk) > base {
					chunk = chunk[base:]
				} else {
					chunk = "\n"
				}
				body.WriteString(chunk)
				li++
			}
			tokens = append(tokens, token{kind: tkString, value: body.String()})
			continue
		}
		// a comment
		if idx := indexYamlComment(rest); idx >= 0 {
			tokens = append(tokens, token{kind: tkComment, value: strings.TrimRight(rest[idx:], " \t")})
			if nl != "" {
				tokens = append(tokens, token{kind: tkText, value: nl})
			}
			continue
		}
		// a sequence entry
		if rest == "-" || strings.HasPrefix(rest, "- ") {
			tokens = append(tokens, token{kind: tkPunctuation, value: "- "})
			item := strings.TrimPrefix(rest, "- ")
			tokens = append(tokens, yamlValue(item)...)
			if nl != "" {
				tokens = append(tokens, token{kind: tkText, value: nl})
			}
			continue
		}
		// a mapping entry: key: value
		if idx := indexYamlColon(rest); idx >= 0 {
			tokens = append(tokens, token{kind: tkNameTag, value: rest[:idx]})
			after := rest[idx:]
			if strings.HasPrefix(after, ":") {
				tokens = append(tokens, token{kind: tkPunctuation, value: ":"})
				after = after[1:]
			}
			tokens = append(tokens, yamlValue(after)...)
			if nl != "" {
				tokens = append(tokens, token{kind: tkText, value: nl})
			}
			continue
		}
		tokens = append(tokens, yamlValue(rest)...)
		if nl != "" {
			tokens = append(tokens, token{kind: tkText, value: nl})
		}
	}
	return tokens
}

// indexYamlComment returns the index of a comment within a line, or -1.
func indexYamlComment(s string) int {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
				return i
			}
		}
	}
	return -1
}

// indexYamlColon returns the index of the key/value separator, or -1.
func indexYamlColon(s string) int {
	inSingle, inDouble := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
