// clangLexer tokenizes C-like source code.
func clangLexer(cfg *clangConfig) lexerFunc {
	return func(text string) []token {
		var tokens []token
		i := 0
		n := len(text)
		for i < n {
			c := text[i]
			if c == ' ' || c == '\t' {
				j := i
				for j < n && (text[j] == ' ' || text[j] == '\t') {
					j++
				}
				tokens = append(tokens, token{kind: tkText, value: text[i:j]})
				i = j
				continue
			}
			if c == '\n' || c == '\r' {
				j := i
				for j < n && (text[j] == '\n' || text[j] == '\r') {
					j++
				}
				tokens = append(tokens, token{kind: tkWhitespace, value: text[i:j]})
				i = j
				continue
			}
			if c == '/' && i+1 < n && text[i+1] == '/' {
				j := i + 2
				for j < n && text[j] != '\n' {
					j++
				}
				if j < n {
					j++
				}
				tokens = append(tokens, token{kind: tkComment, value: text[i:j]})
				i = j
				continue
			}
			if c == '/' && i+1 < n && text[i+1] == '*' {
				j := i + 2
				for j+1 < n && !(text[j] == '*' && text[j+1] == '/') {
					j++
				}
				if j+1 < n {
					j += 2
				} else {
					j = n
				}
				tokens = append(tokens, token{kind: tkComment, value: text[i:j]})
				i = j
				continue
			}
			if cfg.preproc && c == '#' && atLineStart(text, i) {
				j := i + 1
				for j < n && isWordChar(text[j]) {
					j++
				}
				tokens = append(tokens, token{kind: tkComment, value: text[i:j]})
				i = j
				if i < n && (text[i] == ' ' || text[i] == '\t') {
					k := i
					for k < n && (text[k] == ' ' || text[k] == '\t') {
						k++
					}
					tokens = append(tokens, token{kind: tkText, value: text[i:k]})
					i = k
				}
				if i < n && text[i] == '<' {
					k := i
					for k < n && text[k] != '\n' {
						k++
					}
					tokens = append(tokens, token{kind: tkComment, value: text[i:k]})
					if k < n {
						k++
					}
					tokens = append(tokens, token{kind: tkComment, value: text[i+1:k]})
					i = k
					continue
				}
				k := i
				for k < n && text[k] != '\n' {
					k++
				}
				if k < n {
					k++
				}
				tokens = append(tokens, token{kind: tkComment, value: text[i:k]})
				i = k
				continue
			}
			if c == '"' || c == '\'' {
				j := i + 1
				for j < n {
					if text[j] == '\\' {
						j += 2
						continue
					}
					if text[j] == c {
						j++
						break
					}
					j++
				}
				tokens = append(tokens, token{kind: tkString, value: text[i:j]})
				i = j
				continue
			}
			if c >= '0' && c <= '9' {
				j := i
				for j < n && (isWordChar(text[j]) || text[j] == '.') {
					j++
				}
				tokens = append(tokens, token{kind: tkNumber, value: text[i:j]})
				i = j
				continue
			}
			if isNameStart(c) {
				j := i
				for j < n && isWordChar(text[j]) {
					j++
				}
				word := text[i:j]
				switch {
				case cfg.namespace[word]:
					tokens = append(tokens, token{kind: tkKeywordNamespace, value: word})
				case cfg.keywords[word]:
					tokens = append(tokens, token{kind: tkKeyword, value: word})
				default:
					kind := cfg.identStyle
					if cfg.funcCall != cfg.identStyle {
						k := j
						for k < n && (text[k] == ' ' || text[k] == '\t') {
							k++
						}
						if k < n && text[k] == '(' {
							kind = cfg.funcCall
						}
					}
					tokens = append(tokens, token{kind: kind, value: word})
				}
				i = j
				continue
			}
			if isOperator(text, i) {
				j := i
				for j < n && isOperator(text, j) {
					j++
				}
				tokens = append(tokens, token{kind: tkOperator, value: text[i:j]})
				i = j
				continue
			}
			tokens = append(tokens, token{kind: tkPunctuation, value: string(c)})
			i++
		}
		return tokens
	}
}

// atLineStart reports whether position i is at the beginning of a line.
func atLineStart(text string, i int) bool {
	for i > 0 {
		i--
		if text[i] == '\n' {
			return true
		}
		if text[i] != ' ' && text[i] != '\t' {
			return false
		}
	}
	return true
}

var operatorChars = map[byte]bool{
	'=': true, '+': true, '-': true, '*': true, '/': true, '%': true,
	'!': true, '<': true, '>': true, '^': true, '&': true, '|': true,
	'?': true, '~': true, ':': true,
}

func isOperator(text string, i int) bool {
	return operatorChars[text[i]]
}
