			if i+1 < n {
				lit.WriteByte(body[i+1])
			}
			i += 2
			continue
		}
		if body[i] == '{' {
			if i+1 < n && body[i+1] == '{' {
				lit.WriteString("{{")
				i += 2
				continue
			}
			flush()
			// find the closing brace
			depth := 1
			j := i + 1
			for j < n && depth > 0 {
				switch body[j] {
				case '{':
					depth++
				case '}':
					depth--
				}
				j++
			}
