			i = j
			continue
		}
		j := i
		for j < n && !isWhitespace(text[j]) && !isOperator(text, j) && text[j] != '.' {
			j++
		}
		tokens = append(tokens, token{kind: tkPunctuation, value: text[i:j]})
		i = j
	}
	return tokens
}

func isStringPrefix(s string) bool {
	if s == "" || len(s) > 3 {
		return false
	}
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case 'r', 'R', 'b', 'B', 'u', 'U', 'f', 'F':
		default:
			return false
		}
	}
	return true
}

// lexPythonString lexes a Python string literal starting at position i.
func lexPythonString(text string, i int) ([]token, int) {
	n := len(text)
	quote := text[i]
	triple := i+2 < n && text[i+1] == quote && text[i+2] == quote
	fstring := false
	if i > 0 {
		k := i - 1
		for k >= 0 && isNameStart(text[k]) {
			k--
		}
		prefix := strings.ToLower(text[k+1 : i])
		fstring = strings.Contains(prefix, "f")
	}
	var tokens []token
	if !triple {
		j := i + 1
		for j < n {
			if text[j] == '\\' {
				j += 2
				continue
			}
			if text[j] == quote {
				j++
				break
			}
			j++
		}
		body := text[i:j]
		if fstring {
			tokens = append(tokens, splitFString(body, quote, false)...)
		} else {
			tokens = append(tokens, token{kind: tkString, value: body})
		}
		return tokens, j
	}
	j := i + 3
	for j+2 < n {
		if text[j] == '\\' {
			j += 2
			continue
		}
		if text[j] == quote && text[j+1] == quote && text[j+2] == quote {
			j += 3
			break
		}
		j++
	}
	body := text[i:j]
	if fstring {
		tokens = append(tokens, splitFString(body, quote, true)...)
	} else {
		tokens = append(tokens, token{kind: tkString, value: body})
	}
	return tokens, j
}

// splitFString splits an f-string into literal and interpolation tokens.
func splitFString(body string, quote byte, triple bool) []token {
	var tokens []token
	i := 0
	n := len(body)
	var lit strings.Builder
	flush := func() {
		if lit.Len() > 0 {
			tokens = append(tokens, token{kind: tkString, value: lit.String()})
			lit.Reset()
		}
	}
	for i < n {
		if body[i] == '\\' && i+1 < n {
			lit.WriteByte(body[i])
			if i+1 < n {
				lit.WriteByte(body[i+1])
			}
			i += 2
			continue
		}
		if body[i] == '{' {
			if i+1 < n && body[i+1] == '{' {
				lit.WriteString("{{")
				i += 2
				continue
			}
			flush()
			// find the closing brace
			depth := 1
			j := i + 1
			for j < n && depth > 0 {
				switch body[j] {
				case '{':
					depth++
				case '}':
					depth--
				}
				j++
			}
			tokens = append(tokens, token{kind: tkString, value: "{"})
			if j > i+1 {
				tokens = append(tokens, token{kind: tkText, value: body[i+1 : j-1]})
			}
			tokens = append(tokens, token{kind: tkString, value: "}"})
			i = j
			continue
		}
		if body[i] == '}' && i+1 < n && body[i+1] == '}' {
			lit.WriteString("}}")
			i += 2
			continue
		}
		lit.WriteByte(body[i])
		i++
	}
	flush()
	return tokens
}
